export const codingIndex=[{"id":"C-001","language":"c","title":"두 정수의 합","topic":"입출력·변수","level":"입문","statement":"한 줄에 입력된 두 정수를 더한 결과를 출력하시오."},{"id":"C-002","language":"c","title":"Hello World 출력","topic":"입출력","level":"입문","statement":"입력 없이 Hello World를 정확한 대소문자와 공백으로 한 줄에 출력하시오."},{"id":"C-003","language":"c","title":"문자열 두 줄 출력","topic":"입출력","level":"입문","statement":"입력 없이 첫째 줄에 C Language, 둘째 줄에 First Step을 출력하시오."},{"id":"C-004","language":"c","title":"정수 그대로 출력","topic":"입출력","level":"입문","statement":"정수 n 한 개를 표준 입력으로 입력받아, 입력한 값을 변경하지 않고 한 줄에 출력하시오. n은 C 언어의 int 자료형으로 표현 가능한 정수입니다."},{"id":"C-005","language":"c","title":"실수 한 개 출력","topic":"입출력","level":"입문","statement":"0 이상의 실수 x를 하나 입력받아 소수 셋째 자리에서 반올림한 값을 소수 둘째 자리까지(반드시 두 자리 표시) 한 줄에 출력하시오."},{"id":"C-006","language":"c","title":"정수 두 개 서로 다른 줄 출력","topic":"입출력","level":"입문","statement":"공백으로 구분된 두 정수를 입력받아 첫 번째 정수를 첫째 줄에, 두 번째 정수를 둘째 줄에 출력하시오."},{"id":"C-007","language":"c","title":"문자 한 개 입력·출력","topic":"입출력","level":"입문","statement":"공백과 줄바꿈이 아닌 ASCII 문자 ch 한 개를 입력받아 해당 문자를 그대로 한 줄에 출력하시오."},{"id":"C-008","language":"c","title":"정수 세 개 합계","topic":"입출력","level":"입문","statement":"정수 a, b, c 세 개를 이 순서대로 공백으로 구분해 한 줄에 입력받아, 세 정수의 합을 출력하시오."},{"id":"C-009","language":"c","title":"이름 한 단어 출력","topic":"입출력","level":"입문","statement":"공백 없는 영문 이름 한 단어(1~20글자)를 입력받아 'Hello, 이름!' 형식으로 한 줄에 출력하시오."},{"id":"C-010","language":"c","title":"정수와 문자 함께 출력","topic":"입출력","level":"입문","statement":"정수 1개와 공백이 아닌 ASCII 문자 1개를 이 순서대로 공백으로 구분하여 입력받으시오. 정수, 공백 한 칸, 문자를 차례로 한 줄에 출력하시오."},{"id":"C-011","language":"c","title":"정수 제곱 계산","topic":"변수·연산","level":"입문","statement":"정수 N을 한 개 입력받아 N의 제곱을 출력하시오."},{"id":"C-012","language":"c","title":"사칙연산 결과","topic":"변수·연산","level":"입문","statement":"정수 A와 B를 이 순서대로 공백으로 구분해 입력받아, A+B, A-B, A×B의 결과를 각각 한 줄씩 총 3줄에 출력하시오."},{"id":"C-013","language":"c","title":"몫과 나머지","topic":"변수·연산","level":"입문","statement":"0 이상의 정수 A와 양의 정수 B를 이 순서대로 공백으로 구분해 입력받아, A를 B로 나눈 정수 몫과 나머지를 공백으로 구분해 한 줄에 출력하시오."},{"id":"C-014","language":"c","title":"직사각형 넓이·둘레","topic":"변수·연산","level":"입문","statement":"양의 정수인 가로와 세로를 공백으로 구분해 입력받아, 직사각형의 넓이와 둘레를 이 순서대로 공백으로 구분해 한 줄에 출력하시오."},{"id":"C-015","language":"c","title":"삼각형 넓이","topic":"변수·연산","level":"입문","statement":"0 이상의 실수인 밑변과 높이를 공백으로 구분해 입력받아 삼각형의 넓이(밑변 × 높이 ÷ 2)를 소수 셋째 자리에서 반올림하여 소수 둘째 자리까지 출력하시오."},{"id":"C-016","language":"c","title":"섭씨를 화씨로","topic":"변수·연산","level":"입문","statement":"섭씨온도 c를 실수로 입력받아 화씨온도(c × 9 ÷ 5 + 32)를 소수 둘째 자리에서 반올림하여 소수 첫째 자리까지 출력하시오."},{"id":"C-017","language":"c","title":"초를 시·분·초로","topic":"변수·연산","level":"입문","statement":"0 이상의 정수 초 S를 입력받아 시·분·초로 변환한 뒤, 시 분 초 순서로 공백으로 구분해 한 줄에 출력하시오."},{"id":"C-018","language":"c","title":"임시 변수로 값 교환","topic":"변수·연산","level":"입문","statement":"정수 a, b 두 개를 공백으로 구분해 입력받아 임시 변수 temp를 사용해 두 값을 교환한 뒤, 교환된 a와 b를 공백으로 구분해 한 줄에 출력하시오."},{"id":"C-019","language":"c","title":"1씩 증가·감소","topic":"변수·연산","level":"입문","statement":"정수 N을 한 개 입력받아 N+1과 N-1을 공백으로 구분해 한 줄에 출력하시오."},{"id":"C-020","language":"c","title":"복합 대입 연산 추적","topic":"변수·연산","level":"입문","statement":"정수 N을 입력받아 N에 3을 더하고, 그 결과에 2를 곱한 다음, 4를 뺀 최종값을 출력하시오. 연산은 제시한 순서대로 수행하시오."},{"id":"C-021","language":"c","title":"양수·음수·0 판별","topic":"조건문","level":"입문","statement":"정수 N을 한 개 입력받아 양수이면 POSITIVE, 음수이면 NEGATIVE, 0이면 ZERO를 한 줄에 출력하시오."},{"id":"C-022","language":"c","title":"두 정수의 큰 값","topic":"조건문","level":"입문","statement":"서로 다른 두 정수를 공백으로 구분해 입력받아 더 큰 정수를 한 줄에 출력하시오."},{"id":"C-023","language":"c","title":"세 정수 최댓값","topic":"조건문","level":"입문","statement":"정수 세 개를 공백으로 구분해 한 줄에 입력받아 최댓값을 출력하시오."},{"id":"C-024","language":"c","title":"홀수와 짝수 판별","topic":"조건문","level":"입문","statement":"정수 한 개를 입력받아 짝수이면 EVEN, 홀수이면 ODD를 출력하시오."},{"id":"C-025","language":"c","title":"점수 등급 출력","topic":"조건문","level":"입문","statement":"정수 점수 s(0 ≤ s ≤ 100)를 입력받아 90점 이상이면 A, 80점 이상 90점 미만이면 B, 70점 이상 80점 미만이면 C, 60점 이상 70점 미만이면 D, 60점 미만이면 F를 한 글자로 출력하시오."},{"id":"C-026","language":"c","title":"윤년 판별","topic":"조건문","level":"입문","statement":"연도를 입력받으시오. 연도가 400의 배수이거나, 4의 배수이면서 100의 배수가 아니면 윤년입니다. 윤년이면 LEAP, 그렇지 않으면 COMMON을 출력하시오."},{"id":"C-027","language":"c","title":"성인 여부 판별","topic":"조건문","level":"입문","statement":"나이를 입력받으시오. 19세 이상이면 ADULT, 19세 미만이면 MINOR를 출력하시오."},{"id":"C-028","language":"c","title":"3과 5의 공배수","topic":"조건문","level":"입문","statement":"정수 N을 한 개 입력받아 3의 배수이면서 동시에 5의 배수이면 YES, 그렇지 않으면 NO를 출력하시오."},{"id":"C-029","language":"c","title":"두 값 대소 비교","topic":"조건문","level":"입문","statement":"정수 A, B를 공백으로 구분해 입력받아 A가 B보다 크면 >, 작으면 <, 같으면 =를 한 줄에 출력하시오."},{"id":"C-030","language":"c","title":"switch 사칙연산 메뉴","topic":"조건문","level":"입문","statement":"연산 번호(1~4)와 정수 A, B를 순서대로 입력받으시오. 번호가 1이면 합(A+B), 2이면 차(A-B), 3이면 곱(A×B), 4이면 정수 몫(A/B)을 출력하시오. 번호가 4일 때는 B가 0이 아닙니다."},{"id":"C-031","language":"c","title":"1~100 범위 확인","topic":"조건문","level":"입문","statement":"정수 N 한 개를 입력받아 1 ≤ N ≤ 100이면 IN, 그 밖의 값이면 OUT을 출력하시오."},{"id":"C-032","language":"c","title":"영문 대문자 확인","topic":"조건문","level":"입문","statement":"공백과 줄바꿈이 아닌 ASCII 문자 ch 한 개를 입력받아 A~Z에 속하면 UPPER, 그 밖의 문자이면 OTHER를 출력하시오."},{"id":"C-033","language":"c","title":"네 정수 최솟값","topic":"조건문","level":"입문","statement":"정수 네 개를 공백으로 구분해 한 줄에 입력받아 가장 작은 값을 출력하시오."},{"id":"C-034","language":"c","title":"월별 일수 계산","topic":"조건문","level":"입문","statement":"연도 Y와 월 M(1~12)을 입력받으시오. 해당 월의 날짜 수를 출력하시오. 2월은 연도가 400의 배수이거나 4의 배수이면서 100의 배수가 아닌 윤년이면 29일, 그 밖은 28일입니다."},{"id":"C-035","language":"c","title":"구매 금액 할인","topic":"조건문","level":"입문","statement":"구매금액 N(0 이상의 정수, 단위 원)을 입력받아 할인 후 결제금액을 출력하시오. N ≥ 50000이면 10%, 10000 ≤ N < 50000이면 5%, N < 10000이면 0%를 할인하며, 할인액은 정수 나눗셈으로 계산하시오."},{"id":"C-036","language":"c","title":"1부터 N 출력","topic":"반복문","level":"입문","statement":"양의 정수 N을 입력받아 1부터 N까지의 정수를 오름차순으로 공백으로 구분해 한 줄에 출력하시오."},{"id":"C-037","language":"c","title":"N부터 1 출력","topic":"반복문","level":"입문","statement":"양의 정수 N을 입력받아 N부터 1까지의 정수를 내림차순으로 공백으로 구분해 한 줄에 출력하시오."},{"id":"C-038","language":"c","title":"짝수 모두 출력","topic":"반복문","level":"입문","statement":"2 이상의 정수 N을 입력받아 2부터 N까지의 짝수를 오름차순으로 공백으로 구분해 한 줄에 출력하시오."},{"id":"C-039","language":"c","title":"3의 배수 출력","topic":"반복문","level":"입문","statement":"3 이상의 정수 N을 입력받아 N 이하의 양의 3의 배수를 오름차순으로 공백으로 구분해 한 줄에 출력하시오."},{"id":"C-040","language":"c","title":"1부터 N 홀수 합계","topic":"반복문","level":"입문","statement":"양의 정수 N을 입력받아 1부터 N까지의 홀수를 모두 더한 결과를 출력하시오."},{"id":"C-041","language":"c","title":"1부터 N까지 합계","topic":"반복문","level":"입문","statement":"양의 정수 N을 입력받아 1부터 N까지의 모든 정수를 더한 결과를 출력하시오."},{"id":"C-042","language":"c","title":"팩토리얼 계산","topic":"반복문","level":"입문","statement":"정수 N(0 ≤ N ≤ 12)을 입력받아 N!을 출력하시오. 0!은 1입니다."},{"id":"C-043","language":"c","title":"거듭제곱 반복 계산","topic":"반복문","level":"입문","statement":"정수 밑 A(-10 ≤ A ≤ 10)와 정수 지수 B(0 ≤ B ≤ 5)를 공백으로 구분해 입력받아 반복문으로 A의 B제곱을 계산해 출력하시오. B=0이면 A=0인 경우에도 이 문제에서는 1을 출력합니다."},{"id":"C-044","language":"c","title":"특정 단 구구단","topic":"반복문","level":"입문","statement":"정수 N(2 ≤ N ≤ 9)을 입력받아 N단의 곱셈식을 'N*수=결과' 형식으로 1부터 9까지 순서대로 한 줄에 하나씩 출력하시오. 예: 2*1=2 (공백 없음)."},{"id":"C-045","language":"c","title":"2~9단 곱셈표","topic":"반복문","level":"입문","statement":"입력 없이 2단부터 9단까지 각 단의 1부터 9까지 곱한 결과를 '단*수=결과' 형식(예: 2*1=2, 공백 없음)으로 한 줄에 하나씩 총 72줄 출력하시오. 따옴표나 괄호는 출력하지 않습니다."},{"id":"C-046","language":"c","title":"별 직사각형 출력","topic":"반복문","level":"입문","statement":"양의 정수인 행 R과 열 C를 공백으로 구분해 입력받으시오. 별표(*)를 한 행에 C개씩 연달아 출력하고, 이를 총 R행 반복하시오."},{"id":"C-047","language":"c","title":"왼쪽 정렬 별 삼각형","topic":"반복문","level":"입문","statement":"양의 정수 N을 입력받아 첫째 줄에는 * 1개, 둘째 줄에는 * 2개, ..., N번째 줄에는 * N개를 공백 없이 출력하시오."},{"id":"C-048","language":"c","title":"거꾸로 별 삼각형","topic":"반복문","level":"입문","statement":"양의 정수 N을 입력받아 첫째 줄에는 별표(*) N개를, 그다음 줄마다 1개씩 줄여 마지막 줄에는 * 1개를 공백 없이 출력하시오."},{"id":"C-049","language":"c","title":"정수 자릿수","topic":"반복문","level":"기초 응용","statement":"0 이상의 정수 N을 입력받아 십진수 자릿수를 출력하시오. N=0이면 1자리로 계산합니다."},{"id":"C-050","language":"c","title":"정수 뒤집기","topic":"반복문","level":"기초 응용","statement":"정수 N(0 ≤ N ≤ 1,000,000)을 입력받아 십진수 각 자리의 순서를 뒤집은 정수를 출력하시오. 예: 120 → 21 (뒤집은 수 앞의 0은 출력하지 않음)."},{"id":"C-051","language":"c","title":"각 자리 숫자 합","topic":"반복문","level":"기초 응용","statement":"0 이상의 정수 N을 한 개 입력받아 N의 각 자리 숫자를 모두 더한 결과를 출력하시오."},{"id":"C-052","language":"c","title":"소수 판별","topic":"반복문","level":"기초 응용","statement":"2 이상의 정수 N을 입력받아 소수이면 PRIME, 합성수이면 COMPOSITE를 출력하시오."},{"id":"C-053","language":"c","title":"약수 개수","topic":"반복문","level":"기초 응용","statement":"양의 정수 N을 입력받아 N을 나누어떨어지게 하는 양의 정수(약수)의 개수를 출력하시오."},{"id":"C-054","language":"c","title":"최대공약수","topic":"반복문","level":"기초 응용","statement":"양의 정수 A, B를 공백으로 구분해 입력받아 유클리드 호제법으로 최대공약수를 계산해 출력하시오."},{"id":"C-055","language":"c","title":"최소공배수","topic":"반복문","level":"기초 응용","statement":"양의 정수 A, B(각각 1 이상 1000 이하)를 공백으로 구분해 입력받아 최소공배수를 출력하시오. 최대공약수(GCD)를 이용할 수 있습니다."},{"id":"C-056","language":"c","title":"배열 다섯 수 합계","topic":"배열","level":"기초 응용","statement":"정수 5개를 입력받으시오. 다섯 정수의 합을 출력하시오."},{"id":"C-057","language":"c","title":"배열 다섯 수 평균","topic":"배열","level":"기초 응용","statement":"정수 5개를 입력받아 산술평균을 구한 후 소수 둘째 자리에서 반올림하여 소수 첫째 자리까지 출력하시오."},{"id":"C-058","language":"c","title":"배열 최댓값·최솟값","topic":"배열","level":"기초 응용","statement":"정수 5개를 입력받으시오. 최댓값과 최솟값을 이 순서대로 공백으로 구분해 출력하시오."},{"id":"C-059","language":"c","title":"짝수 원소 개수","topic":"배열","level":"기초 응용","statement":"정수 5개를 공백으로 구분해 입력받아 짝수인 원소의 개수를 출력하시오."},{"id":"C-060","language":"c","title":"배열 역순 출력","topic":"배열","level":"기초 응용","statement":"정수 5개를 입력받으시오. 마지막 값부터 첫 번째 값까지 역순으로 공백으로 구분해 출력하시오."},{"id":"C-061","language":"c","title":"배열 값 위치 찾기","topic":"배열","level":"기초 응용","statement":"첫째 줄에 정수 5개를 공백으로 구분해, 둘째 줄에 찾을 정수 T를 입력받으시오. 배열에서 T가 처음 나오는 위치(0부터 시작하는 인덱스)를 출력하고, 없으면 -1을 출력하시오."},{"id":"C-062","language":"c","title":"배열 특정 값 교체","topic":"배열","level":"기초 응용","statement":"첫째 줄에 정수 5개를 공백으로 구분해, 둘째 줄에 정수 A와 B를 공백으로 구분해 입력받으시오. 배열에서 A와 같은 모든 원소를 B로 바꾼 뒤, 배열의 정수 5개를 공백으로 구분해 한 줄에 출력하시오."},{"id":"C-063","language":"c","title":"인접한 원소 차이","topic":"배열","level":"기초 응용","statement":"정수 5개를 차례로 배열 a[0]부터 a[4]까지 입력받으시오. 인접한 두 원소의 차이 a[i+1]-a[i]를 i=0,1,2,3 순서로 계산해, 총 4개의 정수를 공백으로 구분해 한 줄에 출력하시오."},{"id":"C-064","language":"c","title":"오름차순 정렬","topic":"배열","level":"기초 응용","statement":"정수 5개를 공백으로 구분해 한 줄에 입력받아, qsort가 아닌 버블 정렬로 오름차순 정렬한 뒤 5개 값을 공백으로 구분해 한 줄에 출력하시오."},{"id":"C-065","language":"c","title":"2×3 행렬 행별 합","topic":"배열","level":"기초 응용","statement":"2행 3열 행렬의 정수 6개를 첫째 행부터 행 우선 순서로 입력받아, 첫째 행의 합과 둘째 행의 합을 이 순서대로 공백으로 구분해 한 줄에 출력하시오."},{"id":"C-066","language":"c","title":"문자의 ASCII 코드 출력","topic":"문자·문자열 기초","level":"기초 응용","statement":"공백이나 줄바꿈이 아닌 기본 ASCII 문자 1개를 입력받아 해당 문자의 ASCII 코드(정수)를 출력하시오."},{"id":"C-067","language":"c","title":"소문자를 대문자로","topic":"문자·문자열 기초","level":"기초 응용","statement":"영문 소문자(a~z) 하나를 입력받으시오. 대문자로 바꾸어 출력하시오. toupper(ch)를 사용하거나 ASCII 코드 차이를 계산할 수 있습니다."},{"id":"C-068","language":"c","title":"숫자 문자 확인","topic":"문자·문자열 기초","level":"기초 응용","statement":"공백과 줄바꿈이 아닌 ASCII 문자 ch 한 개를 입력받아 숫자 문자 '0'~'9'이면 DIGIT, 그 밖의 문자이면 OTHER를 출력하시오."},{"id":"C-069","language":"c","title":"영문 단어 그대로 출력","topic":"문자·문자열 기초","level":"기초 응용","statement":"공백 없는 영문 단어(1~20글자)를 입력받아 그대로 출력하시오. 문자 배열은 최대 20글자와 문자열 종료 문자 '\\0'을 저장할 수 있도록 선언하시오."},{"id":"C-070","language":"c","title":"문자열 길이 직접 세기","topic":"문자·문자열 기초","level":"기초 응용","statement":"공백 없는 영문 단어(1~20글자)를 입력받으시오. strlen()을 사용하지 말고 반복문으로 글자 수를 직접 세어 출력하시오. 종료 문자 '\\0'은 글자 수에 포함하지 않습니다."},{"id":"C-071","language":"c","title":"strlen으로 길이 계산","topic":"C 문자열 API","level":"기초 응용","statement":"공백 없는 단어(1~30글자)를 입력받으시오. 문자열의 글자 수를 반환하는 strlen() 함수를 사용하여 길이를 출력하시오. 종료 문자 '\\0'은 길이에 포함하지 않습니다."},{"id":"C-072","language":"c","title":"모음 개수 세기","topic":"C 문자열 API","level":"기초 응용","statement":"공백 없는 영문 단어(1~30글자)를 입력받으시오. 영문 대문자를 소문자로 바꿔주는 tolower() 함수를 사용하여 모음(a, e, i, o, u)의 개수를 대소문자 구분 없이 출력하시오."},{"id":"C-073","language":"c","title":"특정 문자 등장 횟수","topic":"C 문자열 API","level":"기초 응용","statement":"공백 없는 ASCII 단어(1글자 이상 30글자 이하)와 공백이 아닌 검색 문자 1개를 차례대로 입력받아, 단어에서 해당 문자가 나타나는 횟수를 출력하시오."},{"id":"C-074","language":"c","title":"strcmp 동등 비교","topic":"C 문자열 API","level":"기초 응용","statement":"공백 없는 단어 2개(각각 1~20글자)를 입력받으시오. strcmp()는 대소문자를 구분해 두 문자열을 비교하고 같으면 0을 반환합니다. 같으면 SAME, 다르면 DIFF를 출력하시오."},{"id":"C-075","language":"c","title":"문자열 사전순 비교","topic":"C 문자열 API","level":"기초 응용","statement":"영문 소문자 단어 2개(각각 1~20글자)를 입력받으시오. strcmp(first, second)는 첫 번째 단어가 사전순으로 앞서면 음수, 뒤서면 양수, 같으면 0을 반환합니다. 앞부분이 같다면 더 짧은 단어가 먼저입니다. 첫 번째가 앞서면 FIRST, 두 번째가 앞서면 SECOND, 같으면 EQUAL을 출력하시오."},{"id":"C-076","language":"c","title":"문자 strchr 찾기","topic":"C 문자열 API","level":"기초 응용","statement":"공백 없는 단어(1~30글자)와 찾을 문자 하나를 입력받으시오. strchr(word, target)는 문자가 처음 등장한 위치의 주소를 반환하며, 없으면 NULL을 반환합니다. 처음 등장한 위치를 0부터 세어 출력하고, 없으면 -1을 출력하시오."},{"id":"C-077","language":"c","title":"공백 포함 줄 입력","topic":"C 문자열 API","level":"기초 응용","statement":"공백이 포함될 수 있는 한 줄(최대 60글자)을 입력받으시오. fgets()로 공백을 포함해 문자 배열에 읽고, 일반 공백(' ')의 개수만 출력하시오. 빈 줄도 입력될 수 있습니다."},{"id":"C-078","language":"c","title":"문자열 뒤집기","topic":"C 문자열 API","level":"기초 응용","statement":"공백 없는 단어(1~30글자)를 입력받으시오. strlen()으로 글자 수를 구한 다음, 마지막 문자부터 첫 문자까지 역순으로 출력하시오."},{"id":"C-079","language":"c","title":"회문 검사","topic":"C 문자열 API","level":"기초 응용","statement":"영문 소문자 단어(1~30글자)를 입력받으시오. strlen()으로 글자 수를 구하고 양쪽 끝의 문자부터 차례대로 비교하시오. 회문이면 YES, 아니면 NO를 출력하시오."},{"id":"C-080","language":"c","title":"두 단어 안전하게 합치기","topic":"C 문자열 API","level":"기초 응용","statement":"공백 없는 영문 단어 2개(각각 1~20글자)를 입력받으시오. snprintf()로 두 단어를 붙인 문자열을 배열 dest에 저장하시오. 배열은 64바이트 이상 확보하고 크기를 초과하지 않도록 제한하시오. 저장한 문자열을 printf()로 출력하시오."},{"id":"C-081","language":"c","title":"정수 제곱 함수","topic":"함수","level":"기초 응용","statement":"정수 N(-1000 ≤ N ≤ 1000)을 입력받아 int square(int n) 함수를 호출하여 N의 제곱을 구하고, 반환된 결과를 출력하시오."},{"id":"C-082","language":"c","title":"두 수 큰 값 함수","topic":"함수","level":"기초 응용","statement":"정수 a, b를 공백으로 구분해 입력받아 int max2(int a, int b) 함수를 호출해 더 큰 값을 구하고 한 줄에 출력하시오."},{"id":"C-083","language":"c","title":"홀짝 판별 함수","topic":"함수","level":"기초 응용","statement":"정수 n 하나를 입력받아 int isEven(int n) 함수를 호출하시오. 함수는 짝수이면 1, 홀수이면 0을 반환하며, 반환값을 한 줄에 출력하시오."},{"id":"C-084","language":"c","title":"1부터 N 합 함수","topic":"함수","level":"기초 응용","statement":"양의 정수 N을 입력받아 int sumTo(int n) 함수를 호출해 1부터 N까지의 합을 구하고 출력하시오."},{"id":"C-085","language":"c","title":"팩토리얼 함수","topic":"함수","level":"기초 응용","statement":"정수 N(0 ≤ N ≤ 12)을 입력받아 int factorial(int n) 함수를 반복문으로 구현하시오. factorial(n)은 1부터 n까지의 정수를 모두 곱한 값(n!)을 반환하며, 0!의 값은 1입니다. 함수가 반환한 팩토리얼 값을 한 줄에 출력하시오."},{"id":"C-086","language":"c","title":"최대공약수 함수","topic":"함수","level":"종합 활용","statement":"양의 정수 A와 B를 공백으로 구분해 입력받아 int gcd(int a, int b) 함수를 호출해 최대공약수를 출력하시오."},{"id":"C-087","language":"c","title":"배열 합계 함수","topic":"함수","level":"종합 활용","statement":"정수 5개를 공백으로 구분해 입력받아 배열에 저장하시오. int sumArray(const int a[], int n) 함수에 배열과 길이 5를 전달해 합계를 구하고 출력하시오."},{"id":"C-088","language":"c","title":"배열 최댓값 함수","topic":"함수","level":"종합 활용","statement":"정수 5개를 공백으로 구분해 입력받아 배열에 저장하시오. int maxArray(const int a[], int n) 함수에 배열과 길이 5를 전달해 최댓값을 구하고 출력하시오."},{"id":"C-089","language":"c","title":"포인터 매개변수로 교환","topic":"함수","level":"종합 활용","statement":"정수 두 개를 공백으로 구분해 입력받아 변수 a, b에 저장하시오. void swap(int *a, int *b) 함수에 두 변수의 주소를 전달해 값을 교환한 뒤, a와 b를 공백으로 구분해 한 줄에 출력하시오."},{"id":"C-090","language":"c","title":"함수 분리 계산기","topic":"함수","level":"종합 활용","statement":"정수 A, B와 연산 번호(1~3)를 공백으로 구분해 순서대로 입력받으시오.\n다음 세 개의 int 반환 함수를 직접 정의하시오.\n- add(int a, int b): 두 정수의 합(a+b)을 반환하는 덧셈 함수\n- sub(int a, int b): 첫 번째 정수에서 두 번째 정수를 뺀 차(a-b)를 반환하는 뺄셈 함수\n- mul(int a, int b): 두 정수의 곱(a*b)을 반환하는 곱셈 함수\n연산 번호가 1이면 add(A, B), 2이면 sub(A, B), 3이면 mul(A, B)를 호출하고, 해당 함수의 반환값을 한 줄에 출력하시오."},{"id":"C-091","language":"c","title":"포인터 간접 참조","topic":"포인터·구조체","level":"종합 활용","statement":"정수 N 한 개를 입력받아 포인터 p가 N이 저장된 변수 n을 가리키게 한 뒤, *p로 읽은 값을 출력하시오."},{"id":"C-092","language":"c","title":"포인터로 변수 변경","topic":"포인터·구조체","level":"종합 활용","statement":"정수 n 한 개를 입력받아 int *p = &n으로 포인터를 만든 뒤, *p에 5를 더하고 변경된 n을 출력하시오."},{"id":"C-093","language":"c","title":"포인터로 배열 순회","topic":"포인터·구조체","level":"종합 활용","statement":"정수 5개를 공백으로 구분해 입력받아 배열에 저장하고, 포인터 산술을 이용해 다섯 정수의 합계를 출력하시오."},{"id":"C-094","language":"c","title":"몫·나머지 출력 매개변수","topic":"포인터·구조체","level":"종합 활용","statement":"정수 a, b(b는 0이 아님)를 공백으로 구분해 입력받으시오. void divide(int a, int b, int *q, int *r) 함수를 정의하시오. 이 함수는 a를 b로 나눈 정수 몫(a/b)을 *q에, 나머지(a%b)를 *r에 저장하고 값을 직접 반환하지 않습니다(void). main 함수에서 q와 r의 주소를 전달한 뒤, 저장된 몫과 나머지를 공백으로 구분해 출력하시오."},{"id":"C-095","language":"c","title":"포인터로 문자열 길이","topic":"포인터·구조체","level":"종합 활용","statement":"공백 없는 단어(1~20글자)를 입력받으시오. char *p 포인터를 문자열 끝의 널 문자('\\0')까지 이동시키면서 글자 수를 세어 출력하시오."},{"id":"C-096","language":"c","title":"학생 구조체 선언","topic":"포인터·구조체","level":"종합 활용","statement":"정수 id와 score를 이 순서대로 공백으로 구분해 입력받아 struct Student의 필드에 저장하고, id와 score를 공백으로 구분해 한 줄에 출력하시오."},{"id":"C-097","language":"c","title":"직사각형 구조체 넓이","topic":"포인터·구조체","level":"종합 활용","statement":"양의 정수인 가로 width와 세로 height를 공백으로 구분해 입력받아 struct Rectangle에 저장하고 넓이를 출력하시오."},{"id":"C-098","language":"c","title":"구조체 배열 최고점 학생","topic":"포인터·구조체","level":"종합 활용","statement":"학생 3명의 번호와 점수를 학생마다 '번호 점수' 순으로 입력받아, 점수가 가장 높은 학생의 번호를 출력하시오. 최고점이 같은 학생이 여럿이면 먼저 입력한 학생의 번호를 출력하시오."},{"id":"C-099","language":"c","title":"구조체로 학생 평균","topic":"포인터·구조체","level":"종합 활용","statement":"학생 3명의 번호와 점수를 학생마다 '번호 점수' 순으로 입력받아 구조체에 저장하고, 세 점수의 평균을 소수 둘째 자리에서 반올림해 소수 첫째 자리까지 출력하시오."},{"id":"C-100","language":"c","title":"구조체 학생 점수 정렬","topic":"포인터·구조체","level":"종합 활용","statement":"학생 3명의 번호와 점수를 각 학생마다 '번호 점수' 순서로 입력받으시오. 학생을 점수 내림차순으로 안정 정렬하여 번호 3개를 공백으로 구분해 한 줄에 출력하시오. 점수가 같으면 먼저 입력한 학생이 앞에 옵니다."},{"id":"JAVA-001","language":"java","title":"Hello World 출력","topic":"출력","level":"입문","statement":"화면에 Hello World를 한 줄 출력하는 프로그램을 작성하시오."},{"id":"JAVA-002","language":"java","title":"두 줄의 문장 출력","topic":"출력과 입력","level":"입문","statement":"입력 없이 첫째 줄에 Hello, 둘째 줄에 Java를 출력하시오."},{"id":"JAVA-003","language":"java","title":"문자열과 숫자 함께 출력","topic":"출력과 입력","level":"입문","statement":"입력 없이 Score: 100을 한 줄에 출력하시오. Score: 뒤에는 공백 한 칸을 넣으시오."},{"id":"JAVA-004","language":"java","title":"특수문자 출력","topic":"출력과 입력","level":"입문","statement":"입력 없이 She said \"Hi\" \\ Java를 한 줄에 출력하시오. 큰따옴표와 역슬래시(\\)까지 정확히 출력하시오."},{"id":"JAVA-005","language":"java","title":"이름 한 단어 입력","topic":"출력과 입력","level":"입문","statement":"영문 이름 한 단어를 입력받으시오. 안녕하세요, 이름 형식으로 한 줄에 출력하시오."},{"id":"JAVA-006","language":"java","title":"정수 입력 후 출력","topic":"출력과 입력","level":"입문","statement":"정수 n을 입력받으시오. 입력받은 값을 그대로 출력하시오."},{"id":"JAVA-007","language":"java","title":"두 정수 다시 출력","topic":"출력과 입력","level":"입문","statement":"공백으로 구분된 정수 2개를 입력받으시오. 첫 번째 정수와 두 번째 정수를 각각 한 줄씩 출력하시오."},{"id":"JAVA-008","language":"java","title":"실수 한 개 출력","topic":"출력과 입력","level":"입문","statement":"실수 하나를 입력받으시오. 소수 둘째 자리까지 항상 두 자리로 출력하시오."},{"id":"JAVA-009","language":"java","title":"한 줄 문장 입력","topic":"출력과 입력","level":"입문","statement":"공백이 포함될 수 있는 문장 한 줄을 입력받으시오. 입력한 문장을 그대로 출력하시오."},{"id":"JAVA-010","language":"java","title":"이름과 나이 서식 출력","topic":"출력과 입력","level":"입문","statement":"공백 없는 이름과 정수 나이를 입력받으시오. name: 이름, age: 나이 형식으로 한 줄에 출력하시오."},{"id":"JAVA-011","language":"java","title":"두 정수의 합","topic":"변수·자료형·연산","level":"입문","statement":"정수 2개를 입력받으시오. 두 정수의 합을 출력하시오."},{"id":"JAVA-012","language":"java","title":"두 정수의 차","topic":"변수·자료형·연산","level":"입문","statement":"정수 2개를 입력받으시오. 첫 번째 정수에서 두 번째 정수를 뺀 결과를 출력하시오."},{"id":"JAVA-013","language":"java","title":"두 정수의 곱","topic":"변수·자료형·연산","level":"입문","statement":"정수 2개를 입력받으시오. 두 정수를 곱한 값을 출력하시오."},{"id":"JAVA-014","language":"java","title":"몫과 나머지 구하기","topic":"변수·자료형·연산","level":"입문","statement":"정수 a와 b(a≥0, b>0)를 입력받으시오. a를 b로 나눈 정수 몫과 나머지를 각각 한 줄씩 출력하시오."},{"id":"JAVA-015","language":"java","title":"세 정수의 평균","topic":"변수·자료형·연산","level":"입문","statement":"정수 3개를 입력받으시오. 세 정수의 평균을 계산하여 소수 둘째 자리까지 출력하시오."},{"id":"JAVA-016","language":"java","title":"초를 분과 초로 변환","topic":"변수·자료형·연산","level":"입문","statement":"0 이상의 정수 초를 입력받으시오. 60으로 나눈 몫은 분, 나머지는 초로 계산하시오. 계산 결과를 2분 5초와 같이 한글 단위를 붙여 한 줄에 출력하시오."},{"id":"JAVA-017","language":"java","title":"원의 넓이 계산","topic":"변수·자료형·연산","level":"입문","statement":"반지름을 입력받아 원주율 3.141592653589793을 사용해 원 넓이를 소수 둘째 자리까지 출력하시오."},{"id":"JAVA-018","language":"java","title":"두 변수의 값 교환","topic":"변수·자료형·연산","level":"입문","statement":"정수 2개를 입력받으시오. 임시 변수를 사용해 두 값을 서로 바꾼 다음, 바뀐 순서로 출력하시오."},{"id":"JAVA-019","language":"java","title":"복합 대입 연산","topic":"변수·자료형·연산","level":"입문","statement":"정수 n을 입력받으시오. n에 5를 더한 뒤 2를 빼고, 최종값을 출력하시오."},{"id":"JAVA-020","language":"java","title":"섭씨를 화씨로 변환","topic":"변수·자료형·연산","level":"입문","statement":"섭씨 온도를 입력받으시오. 화씨 온도로 변환하여 소수 첫째 자리까지 출력하시오."},{"id":"JAVA-021","language":"java","title":"홀수와 짝수 판별","topic":"조건문","level":"입문","statement":"정수 n을 입력받으시오. 짝수이면 EVEN, 홀수이면 ODD를 출력하시오."},{"id":"JAVA-022","language":"java","title":"양수 음수 영 판별","topic":"조건문","level":"입문","statement":"정수 하나를 입력받으시오. 양수이면 POSITIVE, 음수이면 NEGATIVE, 0이면 ZERO를 출력하시오."},{"id":"JAVA-023","language":"java","title":"성인 여부 판별","topic":"조건문","level":"입문","statement":"나이를 입력받으시오. 19세 이상이면 ADULT, 그렇지 않으면 MINOR를 출력하시오."},{"id":"JAVA-024","language":"java","title":"두 정수 중 큰 값","topic":"조건문","level":"입문","statement":"정수 2개를 입력받으시오. 두 정수 중 큰 값을 출력하시오."},{"id":"JAVA-025","language":"java","title":"세 정수의 최댓값","topic":"조건문","level":"입문","statement":"정수 3개를 입력받으시오. 세 정수 중 가장 큰 값을 출력하시오."},{"id":"JAVA-026","language":"java","title":"점수의 학점 판별","topic":"조건문","level":"입문","statement":"점수(0~100)를 입력받으시오. 90점 이상은 A, 80점 이상 90점 미만은 B, 70점 이상 80점 미만은 C, 60점 이상 70점 미만은 D, 60점 미만은 F를 출력하시오."},{"id":"JAVA-027","language":"java","title":"3의 배수 판별","topic":"조건문","level":"입문","statement":"정수 하나를 입력받으시오. 3의 배수이면 YES, 그렇지 않으면 NO를 출력하시오."},{"id":"JAVA-028","language":"java","title":"3과 5의 공배수 판별","topic":"조건문","level":"입문","statement":"양의 정수 n을 입력받으시오. 3과 5로 모두 나누어떨어지면 YES, 그렇지 않으면 NO를 출력하시오."},{"id":"JAVA-029","language":"java","title":"윤년 판별","topic":"조건문","level":"입문","statement":"연도를 입력받으시오. 400의 배수이거나, 4의 배수이면서 100의 배수가 아닌 연도는 윤년입니다. 윤년이면 LEAP, 그렇지 않으면 COMMON을 출력하시오."},{"id":"JAVA-030","language":"java","title":"삼각형 성립 여부","topic":"조건문","level":"입문","statement":"세 양의 정수를 공백으로 구분해 세 변의 길이로 입력받아 삼각형을 만들 수 있으면 YES, 아니면 NO를 출력하시오. 모든 두 변 길이의 합은 나머지 한 변보다 반드시 커야 하며, 같으면 NO입니다."},{"id":"JAVA-031","language":"java","title":"좌표의 사분면","topic":"조건문","level":"입문","statement":"정수 좌표 x, y(둘 다 0이 아님)를 입력받으시오. 해당 좌표가 위치한 사분면의 번호(1~4)를 출력하시오."},{"id":"JAVA-032","language":"java","title":"월의 날짜 수","topic":"조건문","level":"입문","statement":"월을 나타내는 정수(1~12)를 입력받으시오. 평년을 기준으로 해당 월의 날짜 수(28, 30 또는 31)를 출력하시오."},{"id":"JAVA-033","language":"java","title":"할인 금액 계산","topic":"조건문","level":"입문","statement":"0원 이상의 구매 금액을 입력받으시오. 10000원 이상이면 10%를 할인하고, 그렇지 않으면 할인하지 마시오. 할인액은 정수 나눗셈으로 계산하여 최종 결제 금액을 출력하시오."},{"id":"JAVA-034","language":"java","title":"요일 번호를 이름으로","topic":"조건문","level":"입문","statement":"요일 번호(1~7)를 입력받으시오. 1이면 MON, 2이면 TUE, 3이면 WED, 4이면 THU, 5이면 FRI, 6이면 SAT, 7이면 SUN을 출력하시오."},{"id":"JAVA-035","language":"java","title":"월의 계절 구분","topic":"조건문","level":"입문","statement":"월(1~12)을 입력받으시오. 3~5월은 SPRING, 6~8월은 SUMMER, 9~11월은 FALL, 12월과 1~2월은 WINTER를 출력하시오."},{"id":"JAVA-036","language":"java","title":"1부터 N까지 출력","topic":"반복문","level":"입문","statement":"양의 정수 N을 입력받으시오. 1부터 N까지의 정수를 오름차순으로 공백으로 구분해 출력하시오."},{"id":"JAVA-037","language":"java","title":"N부터 1까지 출력","topic":"반복문","level":"입문","statement":"양의 정수 N을 입력받으시오. N부터 1까지의 정수를 내림차순으로 공백으로 구분해 출력하시오."},{"id":"JAVA-038","language":"java","title":"1부터 N까지 짝수 출력","topic":"반복문","level":"입문","statement":"양의 정수 N을 입력받으시오. 1부터 N까지의 양의 짝수를 공백으로 구분해 출력하시오."},{"id":"JAVA-039","language":"java","title":"1부터 N까지 홀수 합","topic":"반복문","level":"입문","statement":"양의 정수 N을 입력받으시오. N 이하인 양의 홀수의 합을 계산해 출력하시오."},{"id":"JAVA-040","language":"java","title":"3의 배수 개수","topic":"반복문","level":"입문","statement":"양의 정수 N을 입력받으시오. 1부터 N까지 3의 배수가 몇 개인지 세어 출력하시오."},{"id":"JAVA-041","language":"java","title":"1부터 N까지의 합","topic":"반복문","level":"입문","statement":"양의 정수 N을 입력받아 1부터 N까지의 합을 출력하시오."},{"id":"JAVA-042","language":"java","title":"팩토리얼 계산","topic":"반복문","level":"입문","statement":"정수 N(0~12)을 입력받으시오. 1부터 N까지의 곱(N!)을 계산해 출력하시오. 0!은 1입니다."},{"id":"JAVA-043","language":"java","title":"입력한 단의 구구단","topic":"반복문","level":"입문","statement":"구구단의 단을 나타내는 정수 N(2~9)을 입력받으시오. N×1부터 N×9까지의 곱셈식을 한 줄씩 총 9줄 출력하시오. 출력 형식은 단 x 수 = 결과입니다."},{"id":"JAVA-044","language":"java","title":"전체 구구단 출력","topic":"반복문","level":"입문","statement":"입력 없이 2단부터 9단까지 구구단을 차례대로 출력하시오. 각 단은 9줄이며, 단과 단 사이에는 빈 줄 한 줄을 넣으시오."},{"id":"JAVA-045","language":"java","title":"양의 정수 자릿수","topic":"반복문","level":"입문","statement":"양의 정수 N을 입력받으시오. 10으로 나누는 반복문을 사용하여 십진수 자릿수를 출력하시오."},{"id":"JAVA-046","language":"java","title":"각 자리의 숫자 더하기","topic":"반복문","level":"입문","statement":"0 이상 1,000,000,000 이하의 정수 N을 입력받으세요. N의 각 자리에 있는 숫자를 모두 더한 값을 출력하세요. 예를 들어 507을 입력하면 백의 자리의 5, 십의 자리의 0, 일의 자리의 7을 더해 12를 출력합니다."},{"id":"JAVA-047","language":"java","title":"정수를 뒤집어 출력","topic":"반복문","level":"입문","statement":"0 이상 1,000,000,000 이하의 정수 N을 입력받으세요. 각 자리 숫자의 순서를 거꾸로 바꾼 정수를 출력하시오. 앞에 오는 0은 생략하며, 뒤집은 값은 int 범위 안에 있습니다."},{"id":"JAVA-048","language":"java","title":"특정 숫자 출현 횟수","topic":"반복문","level":"입문","statement":"0 이상의 정수 N과 찾을 숫자 d(0~9)를 입력받으시오. N값에서 숫자 d가 몇 번 나타나는지 출력하시오."},{"id":"JAVA-049","language":"java","title":"1부터 N까지 제곱 출력","topic":"반복문","level":"입문","statement":"양의 정수 N을 입력받으시오. 1부터 N까지 각 정수의 제곱을 한 줄에 하나씩 출력하시오."},{"id":"JAVA-050","language":"java","title":"종료값 전까지 합산","topic":"반복문","level":"입문","statement":"정수를 차례대로 입력받으시오. -1이 나오면 입력을 멈추고, 그 앞에 입력한 정수의 합을 출력하시오. 종료값 -1은 합계에 포함하지 마시오."},{"id":"JAVA-051","language":"java","title":"do-while 반복 횟수","topic":"반복문","level":"기초 응용","statement":"양의 정수를 반복해서 입력받다가 0이 나오면 멈추시오. 0을 제외한 양의 정수의 개수를 출력하시오."},{"id":"JAVA-052","language":"java","title":"소수 여부 판별","topic":"반복문","level":"기초 응용","statement":"양의 정수 N을 입력받으시오. 소수이면 PRIME, 합성수이면 COMPOSITE, 1이면 NEITHER를 출력하시오."},{"id":"JAVA-053","language":"java","title":"N 이하 소수 개수","topic":"반복문","level":"기초 응용","statement":"양의 정수 N을 입력받으시오. 1부터 N까지 소수가 몇 개인지 세어 출력하시오."},{"id":"JAVA-054","language":"java","title":"최대공약수 구하기","topic":"반복문","level":"기초 응용","statement":"양의 정수 a와 b를 입력받으시오. 유클리드 호제법으로 최대공약수를 계산해 출력하시오."},{"id":"JAVA-055","language":"java","title":"피보나치 수열 출력","topic":"반복문","level":"기초 응용","statement":"정수 N(1~30)을 입력받으시오. 피보나치 수열의 첫 N개 항을 0, 1, 1, 2, ... 순서로 공백으로 구분해 출력하시오."},{"id":"JAVA-056","language":"java","title":"배열의 합계","topic":"배열","level":"기초 응용","statement":"양의 정수 N과 정수 N개를 입력받으시오. 배열에 저장한 정수의 합을 출력하시오."},{"id":"JAVA-057","language":"java","title":"배열의 평균","topic":"배열","level":"기초 응용","statement":"양의 정수 N과 정수 N개를 입력받으시오. 배열 원소의 평균을 소수 둘째 자리까지 출력하시오."},{"id":"JAVA-058","language":"java","title":"배열의 최댓값","topic":"배열","level":"기초 응용","statement":"양의 정수 N과 정수 N개를 입력받으시오. 배열에서 가장 큰 값을 출력하시오."},{"id":"JAVA-059","language":"java","title":"배열의 최솟값","topic":"배열","level":"기초 응용","statement":"양의 정수 N과 정수 N개를 입력받으시오. 배열에서 가장 작은 값을 출력하시오."},{"id":"JAVA-060","language":"java","title":"배열의 홀짝 개수","topic":"배열","level":"기초 응용","statement":"양의 정수 N과 정수 N개를 입력받으시오. 짝수 원소의 개수와 홀수 원소의 개수를 이 순서대로 공백으로 구분해 출력하시오."},{"id":"JAVA-061","language":"java","title":"배열을 역순으로 출력","topic":"배열","level":"기초 응용","statement":"양의 정수 N과 정수 N개를 입력받으시오. 배열의 마지막 원소부터 첫 원소까지 공백으로 구분해 출력하시오."},{"id":"JAVA-062","language":"java","title":"배열의 목표값 개수","topic":"배열","level":"기초 응용","statement":"양의 정수 N, 정수 N개, 찾을 정수 target을 입력받으시오. 배열에서 target과 같은 원소가 몇 개인지 출력하시오."},{"id":"JAVA-063","language":"java","title":"첫 번째 일치 위치","topic":"배열","level":"기초 응용","statement":"양의 정수 N, 정수 N개, 찾을 정수 target을 입력받으시오. 배열에서 target이 처음 나타나는 위치(0부터 시작)를 출력하시오. 없으면 -1을 출력하시오."},{"id":"JAVA-064","language":"java","title":"배열 원소 위치 교환","topic":"배열","level":"기초 응용","statement":"양의 정수 N, 정수 N개, 배열의 위치 i와 j(0≤i,j<N)를 입력받으시오. i번째와 j번째 원소를 교환한 다음 전체 배열을 공백으로 구분해 출력하시오."},{"id":"JAVA-065","language":"java","title":"오름차순 배열인지 검사","topic":"배열","level":"기초 응용","statement":"양의 정수 N과 정수 N개를 입력받으시오. 배열이 앞에서 뒤로 오름차순 또는 같은 값이 이어지는 순서라면 YES, 그렇지 않으면 NO를 출력하시오."},{"id":"JAVA-066","language":"java","title":"문자열 길이","topic":"문자열 기초","level":"입문","statement":"공백 없는 영문·숫자 문자열을 입력받으시오. 문자열의 글자 수를 출력하시오."},{"id":"JAVA-067","language":"java","title":"대문자 소문자 개수","topic":"문자열 기초","level":"기초 응용","statement":"영문 대소문자로만 이루어진 문자열을 입력받으시오. 대문자 개수와 소문자 개수를 공백으로 구분해 출력하시오."},{"id":"JAVA-068","language":"java","title":"문자열 속 숫자 개수","topic":"문자열 기초","level":"기초 응용","statement":"공백 없는 ASCII 문자열을 입력받으시오. '0'부터 '9'까지의 숫자 문자가 몇 개인지 출력하시오."},{"id":"JAVA-069","language":"java","title":"특정 문자 출현 횟수","topic":"문자열 기초","level":"기초 응용","statement":"공백 없는 영문 문자열과 찾을 영문자 하나를 입력받으시오. 문자열에 해당 문자가 나타나는 횟수를 출력하시오."},{"id":"JAVA-070","language":"java","title":"문자열 뒤집기","topic":"문자열 기초","level":"기초 응용","statement":"영문 대소문자로 이루어진 문자열을 입력받으시오. 문자의 순서를 거꾸로 하여 출력하시오."},{"id":"JAVA-071","language":"java","title":"문장 속 공백 개수","topic":"Java 문자열·배열 API","level":"기초 응용","statement":"공백을 포함한 문장 한 줄을 입력받으시오. 일반 공백 문자(U+0020)의 개수를 출력하시오."},{"id":"JAVA-072","language":"java","title":"문자열 양끝 공백 제거","topic":"Java 문자열·배열 API","level":"기초 응용","statement":"공백을 포함한 문장 한 줄을 입력받으시오. 문장 앞뒤의 일반 공백을 제거한 결과를 출력하시오."},{"id":"JAVA-073","language":"java","title":"접두어 일치 여부","topic":"Java 문자열·배열 API","level":"기초 응용","statement":"공백 없는 문자열과 접두어를 입력받으시오. 문자열이 해당 접두어로 시작하면 YES, 그렇지 않으면 NO를 출력하시오."},{"id":"JAVA-074","language":"java","title":"영문 대소문자 변환","topic":"Java 문자열·배열 API","level":"기초 응용","statement":"공백 없는 영문 문자열을 입력받으시오. 모든 문자를 대문자로 바꾼 결과를 첫째 줄에, 소문자로 바꾼 결과를 둘째 줄에 출력하시오."},{"id":"JAVA-075","language":"java","title":"두 문자열 내용 비교","topic":"Java 문자열·배열 API","level":"기초 응용","statement":"공백 없는 문자열 2개를 입력받으시오. 내용이 같으면 SAME, 다르면 DIFFERENT를 출력하시오."},{"id":"JAVA-076","language":"java","title":"문자열 구간 추출","topic":"Java 문자열·배열 API","level":"기초 응용","statement":"공백 없는 문자열 s와 시작 인덱스 start, 종료 인덱스 end를 입력받으시오. String.substring(start, end)는 start 위치의 문자는 포함하고 end 위치의 문자는 포함하지 않는 새 문자열을 반환하는 메서드입니다. 0 ≤ start < end ≤ s.length() 조건을 만족하며, 추출한 문자열을 한 줄에 출력하시오."},{"id":"JAVA-077","language":"java","title":"문장을 단어로 나누기","topic":"Java 문자열·배열 API","level":"기초 응용","statement":"단어 사이를 공백 한 칸으로 구분한 영문 문장을 입력받으시오. 각 단어를 한 줄에 하나씩 출력하시오."},{"id":"JAVA-078","language":"java","title":"문자 치환","topic":"Java 문자열·배열 API","level":"기초 응용","statement":"공백 없는 영문 문자열을 입력받으시오. 문자열에 있는 소문자 a를 모두 @로 바꾸어 출력하시오."},{"id":"JAVA-079","language":"java","title":"정수 배열 정렬","topic":"Java 문자열·배열 API","level":"기초 응용","statement":"양의 정수 N과 정수 N개를 입력받으시오. 오름차순으로 정렬하여 공백으로 구분해 출력하시오."},{"id":"JAVA-080","language":"java","title":"배열 일부 복사","topic":"Java 문자열·배열 API","level":"기초 응용","statement":"양의 정수 N, 정수 N개, 복사할 개수 k(1≤k≤N)를 입력받으시오. 배열의 앞에서부터 k개 원소를 복사하여 공백으로 구분해 출력하시오."},{"id":"JAVA-081","language":"java","title":"두 수의 합 메서드","topic":"메서드","level":"기초 응용","statement":"정수 2개를 입력받으시오. 두 정수의 합을 반환하는 add 메서드를 작성하시오. 메서드 반환값을 출력하시오."},{"id":"JAVA-082","language":"java","title":"두 수의 최댓값 메서드","topic":"메서드","level":"기초 응용","statement":"정수 2개를 입력받으시오. 두 정수 중 큰 값을 반환하는 maxOf 메서드를 작성하시오. 메서드 반환값을 출력하시오."},{"id":"JAVA-083","language":"java","title":"짝수 판별 메서드","topic":"메서드","level":"기초 응용","statement":"정수 하나를 입력받으시오. 짝수이면 true, 홀수이면 false를 반환하는 isEven 메서드를 작성하시오. 반환값에 따라 EVEN 또는 ODD를 출력하시오."},{"id":"JAVA-084","language":"java","title":"1부터 N까지 합 메서드","topic":"메서드","level":"기초 응용","statement":"양의 정수 N을 입력받으시오. 1부터 N까지의 합을 반환하는 sumTo 메서드를 작성하시오. 반환값을 출력하시오."},{"id":"JAVA-085","language":"java","title":"팩토리얼 메서드","topic":"메서드","level":"기초 응용","statement":"정수 N(0 ≤ N ≤ 12)을 입력받아 long factorial(int n) 메서드를 구현하시오. factorial(n)은 1부터 n까지의 모든 정수를 곱한 값(n!)을 반환하며, 0!은 1입니다. 메서드 반환값을 한 줄에 출력하시오."},{"id":"JAVA-086","language":"java","title":"특정 문자 개수 메서드","topic":"메서드","level":"종합 활용","statement":"영문 문자열과 영문자 하나를 입력받으시오. 해당 문자의 등장 횟수를 반환하는 countChar 메서드를 작성하시오. 반환값을 출력하시오."},{"id":"JAVA-087","language":"java","title":"배열 합계 메서드","topic":"메서드","level":"종합 활용","statement":"먼저 양의 정수 N을 입력받고 정수 N개를 배열에 저장하시오. long sumArray(int[] values) 메서드는 전달받은 정수 배열의 모든 원소를 합산한 값을 반환하도록 구현하시오. 메서드 반환값을 한 줄에 출력하시오."},{"id":"JAVA-088","language":"java","title":"배열 최댓값 메서드","topic":"메서드","level":"종합 활용","statement":"먼저 양의 정수 N을 입력받고 정수 N개를 배열에 저장하시오. int maxArray(int[] values) 메서드는 전달받은 배열의 원소 중 가장 큰 정수를 반환하도록 구현하시오. 메서드 반환값을 한 줄에 출력하시오."},{"id":"JAVA-089","language":"java","title":"최대공약수 메서드","topic":"메서드","level":"종합 활용","statement":"양의 정수 a와 b를 입력받으시오. 최대공약수를 반환하는 gcd 메서드를 작성하시오. 메서드 반환값을 출력하시오."},{"id":"JAVA-090","language":"java","title":"값 변경과 반환값 비교","topic":"메서드","level":"종합 활용","statement":"정수 n을 입력받으시오. int increase(int value) 메서드는 전달받은 value에 1을 더한 정수를 반환합니다. 기본형 int 인수는 값이 복사되어 전달되므로 increase(n)을 호출만 해서는 main의 n이 변하지 않습니다. 먼저 increase(n)을 호출한 뒤 원래 n을 출력하고, 다음에는 n = increase(n)으로 반환값을 대입해 바뀐 n을 둘째 줄에 출력하시오."},{"id":"JAVA-091","language":"java","title":"학생 이름과 점수 객체","topic":"클래스·객체·컬렉션","level":"종합 활용","statement":"공백 없는 이름과 점수(0~100)를 입력받으시오. name과 score 필드를 가진 Student 클래스를 작성하고, 객체를 생성하여 이름과 점수를 출력하시오."},{"id":"JAVA-092","language":"java","title":"학생 생성자 정의","topic":"클래스·객체·컬렉션","level":"종합 활용","statement":"공백 없는 이름과 점수(0~100)를 입력받으시오. 이름과 점수를 초기화하는 Student 생성자를 작성하시오. 생성된 객체의 name과 score 필드를 출력하시오."},{"id":"JAVA-093","language":"java","title":"객체 메서드로 점수 변경","topic":"클래스·객체·컬렉션","level":"종합 활용","statement":"초기 점수와 증가 점수(각각 0~100, 합은 100 이하)를 입력받으시오. Student 객체는 int score 필드를 가지며, void addScore(int point) 메서드는 현재 score에 전달받은 point만큼 더해 객체의 점수를 변경합니다. 반환값은 없습니다. 초기 점수로 객체를 생성하고 addScore를 호출한 뒤 변경된 점수를 출력하시오."},{"id":"JAVA-094","language":"java","title":"private 필드와 getter","topic":"클래스·객체·컬렉션","level":"종합 활용","statement":"공백 없는 이름과 점수를 입력받아 Student 객체를 생성하시오. Student의 score 필드는 private으로 선언하여 클래스 밖에서 직접 접근하지 못하도록 하세요. int getScore() 메서드는 이 private 점수 필드의 현재 값을 읽어 int로 반환하는 getter입니다. getScore()가 반환한 점수를 한 줄에 출력하시오."},{"id":"JAVA-095","language":"java","title":"생성한 객체 수 세기","topic":"클래스·객체·컬렉션","level":"종합 활용","statement":"양의 정수 N을 입력받으시오. Student 객체를 N개 생성하고, static count 필드로 생성된 객체의 개수를 세어 출력하시오."},{"id":"JAVA-096","language":"java","title":"ArrayList에 점수 저장","topic":"클래스·객체·컬렉션","level":"종합 활용","statement":"양의 정수 N과 점수 N개(각각 0~100)를 입력받으시오. ArrayList<Integer>에 저장하고 입력 순서대로 공백으로 구분해 출력하시오."},{"id":"JAVA-097","language":"java","title":"ArrayList 합계 계산","topic":"클래스·객체·컬렉션","level":"종합 활용","statement":"양의 정수 N과 정수 N개를 입력받으시오. ArrayList에 저장한 뒤 반복문으로 모든 값을 더해 출력하시오."},{"id":"JAVA-098","language":"java","title":"ArrayList에서 값 검색","topic":"클래스·객체·컬렉션","level":"종합 활용","statement":"양의 정수 N, 정수 N개, 찾을 값 target을 입력받으시오. ArrayList의 contains 메서드로 target이 있는지 검사하여 있으면 YES, 없으면 NO를 출력하시오."},{"id":"JAVA-099","language":"java","title":"학생 객체 목록 평균","topic":"클래스·객체·컬렉션","level":"종합 활용","statement":"양의 정수 N을 입력받고 학생 N명의 이름과 점수(0~100)를 차례대로 입력받으시오. Student 객체를 리스트에 저장하고 평균 점수를 소수 첫째 자리까지 출력하시오."},{"id":"JAVA-100","language":"java","title":"도서 대출 가능 여부","topic":"클래스·객체·컬렉션","level":"종합 활용","statement":"양의 정수 N을 입력받고 도서 N개의 제목 한 단어와 대출 여부를 차례대로 입력받으시오. 대출 여부는 0이 대출 가능, 1이 대출 중을 뜻합니다. Book 클래스의 title, borrowed 필드를 사용해 대출 가능한 도서 제목만 입력 순서대로 한 줄에 하나씩 출력하시오. 해당 도서가 없으면 NONE을 출력하시오."},{"id":"LINUX-001","language":"linux","title":"프로젝트 폴더와 빈 파일 만들기","topic":"파일·디렉터리","level":"입문","statement":"현재 디렉터리에 project 폴더를 만들고 그 안에 src 폴더를 생성하시오. Vim으로 src 폴더에 빈 main.py 파일을 저장하시오. 마지막으로 생성한 폴더와 파일을 확인하시오."},{"id":"LINUX-002","language":"linux","title":"파일을 만들고 접근 권한 설정하기","topic":"파일 권한","level":"입문","statement":"Vim으로 빈 report.txt 파일을 저장하시오. 파일 소유자에게 읽기·쓰기, 그룹에 읽기 권한을 주고 다른 사용자에게는 권한을 주지 마시오. 설정된 권한을 확인하시오."},{"id":"LINUX-003","language":"linux","title":"현재 위치 확인하기","topic":"디렉터리 탐색","level":"입문","statement":"현재 작업 중인 디렉터리의 전체 경로를 출력하시오."},{"id":"LINUX-004","language":"linux","title":"현재 디렉터리의 파일·폴더 확인","topic":"디렉터리 탐색","level":"입문","statement":"현재 폴더에 있는 파일과 디렉터리의 이름을 출력하시오."},{"id":"LINUX-005","language":"linux","title":"숨김 파일 포함하여 목록 확인","topic":"디렉터리 탐색","level":"입문","statement":"현재 폴더에 있는 숨김 파일을 포함해 모든 항목의 이름을 출력하시오."},{"id":"LINUX-006","language":"linux","title":"파일 종류 기호 확인하기","topic":"디렉터리 탐색","level":"입문","statement":"현재 폴더에 있는 파일과 디렉터리의 이름을 종류 구분 기호와 함께 출력하시오."},{"id":"LINUX-007","language":"linux","title":"상세 파일 정보 읽기","topic":"파일 속성","level":"입문","statement":"note.txt 파일의 접근 권한, 소유자, 크기, 수정 시간을 자세히 확인하시오."},{"id":"LINUX-008","language":"linux","title":"한 단계 상위로 이동하기","topic":"디렉터리 탐색","level":"입문","statement":"project 폴더에서 한 단계 위인 lab 폴더로 이동하시오. 이동한 뒤 현재 디렉터리 경로를 확인하시오."},{"id":"LINUX-009","language":"linux","title":"홈 디렉터리로 이동하기","topic":"디렉터리 탐색","level":"입문","statement":"현재 위치에서 자신의 홈 디렉터리로 이동하시오. 이동한 위치의 전체 경로를 출력하시오."},{"id":"LINUX-010","language":"linux","title":"새 폴더 만들기","topic":"디렉터리 생성","level":"입문","statement":"현재 폴더에 reports라는 새 디렉터리를 생성하시오. 생성된 이름을 확인하시오."},{"id":"LINUX-011","language":"linux","title":"Vim으로 빈 텍스트 파일 저장하기","topic":"문서 편집","level":"입문","statement":"Vim으로 빈 note.txt 파일을 저장하고 편집기를 종료하시오. 파일이 생성되었는지 확인하시오."},{"id":"LINUX-012","language":"linux","title":"빈 폴더 삭제하기","topic":"디렉터리 삭제","level":"입문","statement":"내용이 없는 empty 디렉터리를 삭제하시오. 삭제한 뒤 목록에 empty가 없는지 확인하시오."},{"id":"LINUX-013","language":"linux","title":"텍스트 파일 내용 확인하기","topic":"파일 내용","level":"입문","statement":"readme.txt 파일에 저장된 글을 터미널에 출력하시오."},{"id":"LINUX-014","language":"linux","title":"텍스트 파일 복사하기","topic":"파일 복사","level":"입문","statement":"현재 폴더에 있는 note.txt를 backup.txt라는 이름으로 복사하시오. 원본과 복사본이 모두 있는지 확인하시오."},{"id":"LINUX-015","language":"linux","title":"파일 이름 바꾸기","topic":"파일 이동","level":"입문","statement":"현재 폴더의 draft.txt 파일 이름을 final.txt로 바꾸시오. 변경 전 이름이 사라지고 변경 후 이름만 보이는지 확인하시오."},{"id":"LINUX-016","language":"linux","title":"폴더 자체의 상세 정보 확인","topic":"디렉터리 정보","level":"기초 응용","statement":"docs 디렉터리 안의 파일 목록이 아니라 docs 디렉터리 자체의 상세 정보를 확인하시오."},{"id":"LINUX-017","language":"linux","title":"파일의 마지막 일곱 줄 확인","topic":"파일 내용","level":"기초 응용","statement":"현재 폴더에 있는 log.txt 파일의 마지막 7줄만 출력하시오."},{"id":"LINUX-018","language":"linux","title":"검색 결과의 행 번호 함께 보기","topic":"파일 검색","level":"기초 응용","statement":"app.log 파일에서 ERROR가 들어 있는 줄을 찾으시오. 해당 줄의 번호도 함께 출력하시오."},{"id":"LINUX-019","language":"linux","title":"내 계정이 소유한 파일 찾기","topic":"파일 검색","level":"기초 응용","statement":"현재 디렉터리(~/lab)의 소유자는 student이며, 아래 목록의 세 번째 열에 표시된 소유자를 참고하여 현재 폴더와 하위 폴더에서 student 사용자가 소유한 파일 및 디렉터리의 경로만 검색하시오."},{"id":"LINUX-020","language":"linux","title":"명령어가 저장된 위치 확인","topic":"파일 위치","level":"기초 응용","statement":"mv 명령어의 실행 파일이 저장된 경로를 확인하시오."},{"id":"LINUX-021","language":"linux","title":"심볼릭 링크 생성과 원본 파일 비교","topic":"파일 링크","level":"기초 응용","statement":"현재 디렉터리에 있는 data.txt를 가리키는 data-link 심볼릭 링크를 생성하시오. 링크가 가리키는 파일 이름을 확인하고, 원본과 링크의 inode 번호를 비교하시오."},{"id":"LINUX-022","language":"linux","title":"하드 링크와 심볼릭 링크 비교하기","topic":"파일 링크","level":"기초 응용","statement":"현재 디렉터리에 있는 data.txt를 이용하여 data-hard 하드 링크와 data-link 심볼릭 링크를 각각 생성하시오. 원본과 두 링크의 inode 번호를 비교하고, 상세 목록에서 링크 종류와 하드 링크 개수를 확인하시오."},{"id":"LINUX-023","language":"linux","title":"문장 입력 후 저장하기","topic":"Vim 문서 편집","level":"기초 응용","statement":"Vim에서 memo.txt를 새로 열고 첫 줄에 linux study를 입력하시오. 저장한 후 파일 내용을 확인하시오."},{"id":"LINUX-024","language":"linux","title":"특정 행 삭제하기","topic":"Vim 문서 편집","level":"기초 응용","statement":"Vim에서 memo.txt의 두 번째 줄을 삭제하시오. 파일을 저장한 후 남은 내용을 확인하시오."},{"id":"LINUX-025","language":"linux","title":"파일 전체 문자열 바꾸기","topic":"Vim 문서 편집","level":"기초 응용","statement":"Vim에서 memo.txt에 들어 있는 linux를 모두 Linux로 변경하시오. 저장한 후 바뀐 파일 내용을 확인하시오."},{"id":"LINUX-026","language":"linux","title":"기호 모드로 쓰기 권한 제거","topic":"파일 권한","level":"기초 응용","statement":"note.txt 파일의 소유자에게 부여된 쓰기 권한만 제거하시오. 다른 사용자의 권한은 그대로 두고 변경 결과를 확인하시오."},{"id":"LINUX-027","language":"linux","title":"그룹에 두 가지 권한 추가","topic":"파일 권한","level":"기초 응용","statement":"note.txt 파일의 그룹에 쓰기와 실행 권한을 추가하시오. 기존 읽기 권한은 유지하고 변경된 결과를 확인하시오."},{"id":"LINUX-028","language":"linux","title":"기본 권한 마스크 문자로 확인","topic":"파일 권한","level":"기초 응용","statement":"현재 셸에서 사용하는 기본 파일 접근 권한 마스크를 문자 형식으로 출력하시오."},{"id":"LINUX-029","language":"linux","title":"줄바꿈 없이 문자열 출력하기","topic":"셸 출력","level":"기초 응용","statement":"Hello라는 문자열을 출력하되, 출력 끝에 줄바꿈 문자가 추가되지 않도록 하시오."},{"id":"LINUX-030","language":"linux","title":"정수와 줄바꿈 형식 지정","topic":"셸 출력","level":"기초 응용","statement":"정수 12를 십진 정수 형식으로 출력한 뒤 줄바꿈하시오."},{"id":"LINUX-031","language":"linux","title":"변숫값과 문자 그대로 출력 비교","topic":"셸 특수문자","level":"기초 응용","statement":"SHELL 환경 변수에 저장된 경로를 출력하시오. 이어서 변수 대신 $SHELL이라는 글자가 그대로 나오도록 출력하시오."},{"id":"LINUX-032","language":"linux","title":"출력을 파일에 저장하기","topic":"셸 리다이렉션","level":"기초 응용","statement":"hello 문자열을 화면에 출력하지 말고 result.txt 파일에 저장하시오. 저장한 파일의 내용을 확인하시오."},{"id":"LINUX-033","language":"linux","title":"기존 파일 끝에 내용 추가","topic":"셸 리다이렉션","level":"기초 응용","statement":"result.txt 파일의 기존 hello 아래에 world를 새 줄로 추가하시오. 기존 내용을 유지한 상태에서 파일 전체를 확인하시오."},{"id":"LINUX-034","language":"linux","title":"명령어 별명 설정과 확인","topic":"셸 에일리어스","level":"기초 응용","statement":"현재 셸에서 ls 명령을 실행할 때 파일 종류 기호를 함께 표시하도록 별명을 설정하시오. 등록한 별명을 확인하시오."},{"id":"LINUX-035","language":"linux","title":"세 가지 명령을 차례로 실행","topic":"셸 명령 연결","level":"기초 응용","statement":"현재 날짜와 시각을 표시하고, 이어서 현재 폴더의 목록과 작업 디렉터리 경로를 순서대로 출력하시오."},{"id":"LINUX-036","language":"linux","title":"현재 터미널 프로세스 상세 보기","topic":"프로세스","level":"기초 응용","statement":"현재 터미널에서 실행 중인 프로세스의 PID, 부모 프로세스 번호(PPID), 실행 명령 등 자세한 정보를 출력하시오."},{"id":"LINUX-037","language":"linux","title":"시스템 전체 프로세스 자세히 보기","topic":"프로세스","level":"기초 응용","statement":"현재 터미널뿐 아니라 시스템 전체에서 실행 중인 프로세스의 상세 정보를 출력하시오."},{"id":"LINUX-038","language":"linux","title":"bash 프로세스 이름 함께 검색","topic":"프로세스","level":"기초 응용","statement":"이름에 bash가 포함된 프로세스의 PID와 프로세스 이름을 함께 출력하시오."},{"id":"LINUX-039","language":"linux","title":"CPU·메모리 사용량 함께 확인","topic":"프로세스","level":"기초 응용","statement":"시스템에서 실행 중인 프로세스의 사용자 이름, CPU 사용 비율, 메모리 사용 비율을 함께 출력하시오."},{"id":"LINUX-040","language":"linux","title":"파일 시스템의 남은 공간 확인","topic":"디스크","level":"기초 응용","statement":"현재 파일 시스템의 전체 용량, 사용한 공간, 남은 공간을 GB·MB 등 읽기 쉬운 단위로 표시하시오."},{"id":"LINUX-041","language":"linux","title":"파일 시스템 유형과 폴더 사용량 비교","topic":"디스크 종합","level":"종합 활용","statement":"먼저 파일 시스템의 종류를 확인하시오. 이어서 docs 폴더가 사용하는 전체 공간을 읽기 쉬운 단위로 출력하시오."},{"id":"LINUX-042","language":"linux","title":"전체 목록에서 특정 이름의 프로세스 찾기","topic":"프로세스 종합","level":"종합 활용","statement":"시스템 전체 프로세스의 상세 목록에서 bash라는 문자열이 들어 있는 줄만 검색하여 출력하시오."},{"id":"LINUX-043","language":"linux","title":"예정된 시스템 재시작 취소하기","topic":"시스템 종료","level":"종합 활용","statement":"시스템 재시작이 예약되어 있을 때 해당 예약을 취소하는 명령을 작성하시오. 실제 시스템을 종료하거나 재시작하지 않고 예약 취소 명령만 작성하시오."},{"id":"LINUX-044","language":"linux","title":"패키지 검색 후 의존성 확인","topic":"패키지 관리","level":"종합 활용","statement":"APT 캐시에서 이름이나 설명에 vim이 들어 있는 패키지를 검색하시오. 이어서 vim 패키지의 의존성 정보를 조회하시오."},{"id":"LINUX-045","language":"linux","title":"디렉터리를 묶고 목록 확인하기","topic":"파일 아카이브","level":"종합 활용","statement":"docs 폴더와 그 안의 note.txt 파일을 backup.tar 파일로 묶으시오. 이어서 아카이브 안에 들어 있는 파일 목록을 확인하시오."},{"id":"LINUX-046","language":"linux","title":"기존 아카이브 파일 추출하기","topic":"파일 아카이브","level":"종합 활용","statement":"현재 폴더에 있는 backup.tar 아카이브에서 docs 폴더와 note.txt 파일을 추출하시오. 추출한 파일을 확인하시오."},{"id":"LINUX-047","language":"linux","title":"압축 후 압축 파일의 내용 확인","topic":"파일 압축","level":"종합 활용","statement":"report.txt 파일을 gzip 형식으로 압축하시오. 압축을 해제하지 않고 압축된 파일의 내용을 화면에 출력하시오."},{"id":"LINUX-048","language":"linux","title":"로그인 사용자와 소속 그룹 확인","topic":"사용자 정보","level":"종합 활용","statement":"현재 시스템에 로그인한 사용자의 정보를 제목과 함께 출력하시오. 이어서 현재 사용자가 속한 그룹을 출력하시오."},{"id":"LINUX-049","language":"linux","title":"현재 예약된 반복 작업 확인","topic":"작업 예약","level":"종합 활용","statement":"현재 사용자에게 등록된 반복 실행 예약 작업을 확인하시오. 예약 작업이 없는 경우 표시되는 메시지도 확인하시오."},{"id":"LINUX-050","language":"linux","title":"사용자 생성 기본 설정 확인","topic":"사용자 계정","level":"종합 활용","statement":"새 계정을 만들지 않고 사용자 계정 생성 명령의 기본 그룹·홈 디렉터리·셸 설정을 출력하시오."},{"id":"PY-001","language":"python","title":"두 정수의 합","topic":"입출력·변수","level":"입문","statement":"두 줄에 걸쳐 입력받은 정수 두 개의 합을 출력하시오."},{"id":"PY-002","language":"python","title":"Hello World 출력","topic":"입력·출력","level":"입문","statement":"입력 없이 Hello World를 정확히 한 줄에 출력하시오."},{"id":"PY-003","language":"python","title":"문자열 두 줄 출력","topic":"입력·출력","level":"입문","statement":"입력 없이 첫째 줄에 Python, 둘째 줄에 First Step을 출력하시오."},{"id":"PY-004","language":"python","title":"정수 그대로 출력","topic":"입력·출력","level":"입문","statement":"정수 하나를 입력받아 그대로 한 줄에 출력하시오."},{"id":"PY-005","language":"python","title":"실수 둘째 자리 출력","topic":"입력·출력","level":"입문","statement":"실수 x를 입력받아 f-string으로 소수 셋째 자리에서 반올림한 결과를 소수 둘째 자리까지(항상 두 자리 표시) 출력하시오."},{"id":"PY-006","language":"python","title":"정수 두 개 줄바꿈 출력","topic":"입력·출력","level":"입문","statement":"한 줄에 공백으로 구분된 정수 2개를 입력받으시오. 첫 번째 정수와 두 번째 정수를 각각 한 줄씩 출력하시오."},{"id":"PY-007","language":"python","title":"문자 한 글자 출력","topic":"입력·출력","level":"입문","statement":"공백이 아닌 영문 ASCII 문자 하나를 입력받아 그대로 출력하시오."},{"id":"PY-008","language":"python","title":"세 정수의 합","topic":"입력·출력","level":"입문","statement":"정수 3개를 공백으로 구분해 입력받으시오. 세 정수의 합을 출력하시오."},{"id":"PY-009","language":"python","title":"이름 한 단어 인사","topic":"입력·출력","level":"입문","statement":"공백 없는 영문 이름을 입력받으시오. Hello, 이름! 형식으로 출력하시오."},{"id":"PY-010","language":"python","title":"정수와 문자 함께 출력","topic":"입력·출력","level":"입문","statement":"정수 1개와 공백 없는 영문 문자 1개를 공백으로 구분해 입력받으시오. 두 값을 입력 순서대로 공백 한 칸으로 구분해 출력하시오."},{"id":"PY-011","language":"python","title":"정수 제곱 계산","topic":"변수·자료형·연산","level":"입문","statement":"정수 N을 입력받으시오. N의 제곱을 계산하여 출력하시오."},{"id":"PY-012","language":"python","title":"정수 합·차·곱","topic":"변수·자료형·연산","level":"입문","statement":"정수 A와 B를 한 줄에 입력받으시오. A+B, A-B, A×B의 결과를 순서대로 한 줄씩, 총 3줄에 출력하시오."},{"id":"PY-013","language":"python","title":"정수 몫과 나머지","topic":"변수·자료형·연산","level":"입문","statement":"0 이상의 정수 A와 양의 정수 B를 입력받으시오. A를 B로 나눈 정수 몫과 나머지를 공백으로 구분해 출력하시오."},{"id":"PY-014","language":"python","title":"직사각형 넓이·둘레","topic":"변수·자료형·연산","level":"입문","statement":"직사각형의 양의 정수인 가로와 세로 길이를 입력받으시오. 넓이와 둘레를 계산하여 이 순서대로 공백으로 구분해 출력하시오."},{"id":"PY-015","language":"python","title":"삼각형 넓이","topic":"변수·자료형·연산","level":"입문","statement":"0 이상의 실수인 밑변과 높이를 공백으로 구분해 입력받아 삼각형의 넓이(밑변 × 높이 ÷ 2)를 소수 둘째 자리에서 반올림하여 소수 첫째 자리까지 출력하시오."},{"id":"PY-016","language":"python","title":"섭씨를 화씨로","topic":"변수·자료형·연산","level":"입문","statement":"섭씨온도 c를 실수로 입력받아 화씨온도(c × 9 ÷ 5 + 32)를 소수 둘째 자리에서 반올림해 소수 첫째 자리까지 출력하시오."},{"id":"PY-017","language":"python","title":"초를 시·분·초로","topic":"변수·자료형·연산","level":"입문","statement":"초를 0 이상의 정수로 입력받으시오. 이를 시간, 분, 초로 변환하여 공백으로 구분해 출력하시오."},{"id":"PY-018","language":"python","title":"임시 변수로 값 교환","topic":"변수·자료형·연산","level":"입문","statement":"정수 A와 B를 입력받으시오. 임시 변수를 사용해 두 값을 교환한 뒤, 바뀐 값을 공백으로 구분해 출력하시오."},{"id":"PY-019","language":"python","title":"1 증가·1 감소","topic":"변수·자료형·연산","level":"입문","statement":"정수 N을 입력받으시오. N+1과 N-1을 이 순서대로 공백으로 구분해 출력하시오."},{"id":"PY-020","language":"python","title":"복합 대입 연산 순서","topic":"변수·자료형·연산","level":"입문","statement":"정수 N을 입력받으시오. N에 3을 더하고, 결과에 2를 곱한 뒤, 4를 빼시오. 최종값을 출력하시오."},{"id":"PY-021","language":"python","title":"양수·음수·0 판별","topic":"조건문","level":"입문","statement":"정수 하나를 입력받으시오. 양수이면 POSITIVE, 음수이면 NEGATIVE, 0이면 ZERO를 출력하시오."},{"id":"PY-022","language":"python","title":"두 정수 큰 값","topic":"조건문","level":"입문","statement":"서로 다른 정수 2개를 입력받으시오. 두 정수 중 큰 값을 출력하시오."},{"id":"PY-023","language":"python","title":"세 정수 최댓값","topic":"조건문","level":"입문","statement":"정수 3개를 입력받으시오. if 조건문을 사용해 가장 큰 값을 찾고 출력하시오. 단, max() 함수는 사용하지 마시오."},{"id":"PY-024","language":"python","title":"홀짝 판별","topic":"조건문","level":"입문","statement":"정수 하나를 입력받으시오. 짝수이면 EVEN, 홀수이면 ODD를 출력하시오."},{"id":"PY-025","language":"python","title":"점수 등급 판별","topic":"조건문","level":"입문","statement":"0~100 범위의 점수 하나를 입력받으시오. 90점 이상은 A, 80점 이상 90점 미만은 B, 70점 이상 80점 미만은 C, 60점 이상 70점 미만은 D, 그 밖은 F를 출력하시오."},{"id":"PY-026","language":"python","title":"윤년 판별","topic":"조건문","level":"입문","statement":"연도를 입력받으시오. 연도가 400의 배수이거나, 4의 배수이면서 100의 배수가 아니면 윤년입니다. 윤년이면 LEAP, 그렇지 않으면 COMMON을 출력하시오."},{"id":"PY-027","language":"python","title":"나이에 따른 구분","topic":"조건문","level":"입문","statement":"나이를 입력받아 이 문제에서 정한 기준에 따라 19세 이상이면 ADULT, 19세 미만이면 MINOR를 출력하시오."},{"id":"PY-028","language":"python","title":"3과 5의 공배수","topic":"조건문","level":"입문","statement":"양의 정수 N을 입력받으시오. 3과 5의 공배수이면 YES, 그렇지 않으면 NO를 출력하시오."},{"id":"PY-029","language":"python","title":"두 값 대소 비교","topic":"조건문","level":"입문","statement":"정수 A와 B를 입력받으시오. A가 B보다 크면 >, 작으면 <, 같으면 =를 출력하시오."},{"id":"PY-030","language":"python","title":"사칙연산 메뉴","topic":"조건문","level":"입문","statement":"연산 번호(1~4)와 정수 A, B를 순서대로 입력받으시오. 번호가 1이면 합(A+B), 2이면 차(A-B), 3이면 곱(A×B), 4이면 정수 몫(A//B)을 출력하시오. 번호가 4일 때는 A가 0 이상, B가 1 이상입니다."},{"id":"PY-031","language":"python","title":"1~100 범위 확인","topic":"조건문","level":"입문","statement":"정수 N을 입력받으시오. 1 이상 100 이하이면 IN, 그 밖의 값이면 OUT을 출력하시오."},{"id":"PY-032","language":"python","title":"영문 대문자 확인","topic":"조건문","level":"입문","statement":"영문 ASCII 문자 하나를 입력받으시오. A부터 Z까지의 대문자이면 UPPER, 그 밖의 문자이면 OTHER를 출력하시오."},{"id":"PY-033","language":"python","title":"네 정수 최솟값","topic":"조건문","level":"입문","statement":"정수 4개를 입력받으시오. min() 함수를 사용하지 않고 가장 작은 값을 찾아 출력하시오."},{"id":"PY-034","language":"python","title":"월별 일수 계산","topic":"조건문","level":"입문","statement":"연도와 월(1~12)을 입력받으시오. 해당 월의 날짜 수를 출력하시오. 연도가 400의 배수이거나 4의 배수이면서 100의 배수는 아니면 윤년이며, 윤년의 2월은 29일입니다."},{"id":"PY-035","language":"python","title":"구매 금액 할인","topic":"조건문","level":"입문","statement":"0원 이상의 구매 금액 N을 입력받으시오. 50000원 이상은 10%, 10000원 이상 50000원 미만은 5%를 할인하며, 그 밖은 할인하지 않습니다. 할인액은 정수 나눗셈으로 계산하고 최종 결제 금액을 출력하시오."},{"id":"PY-036","language":"python","title":"1부터 N까지 출력","topic":"반복문","level":"입문","statement":"양의 정수 N을 입력받으시오. 1부터 N까지의 정수를 공백으로 구분해 출력하시오."},{"id":"PY-037","language":"python","title":"N부터 1까지 출력","topic":"반복문","level":"입문","statement":"양의 정수 N을 입력받으시오. N부터 1까지의 정수를 내림차순으로 공백으로 구분해 출력하시오."},{"id":"PY-038","language":"python","title":"짝수 모두 출력","topic":"반복문","level":"입문","statement":"2 이상의 정수 N을 입력받으시오. N 이하의 양의 짝수를 오름차순으로 공백으로 구분해 출력하시오."},{"id":"PY-039","language":"python","title":"3의 배수 출력","topic":"반복문","level":"입문","statement":"3 이상의 정수 N을 입력받으시오. N 이하의 양의 3의 배수를 오름차순으로 공백으로 구분해 출력하시오."},{"id":"PY-040","language":"python","title":"홀수 합계","topic":"반복문","level":"입문","statement":"양의 정수 N을 입력받으시오. 1부터 N까지 홀수만 더한 합을 출력하시오."},{"id":"PY-041","language":"python","title":"1부터 N까지의 합","topic":"반복문","level":"입문","statement":"양의 정수 N을 입력받아 1부터 N까지의 합을 출력하시오."},{"id":"PY-042","language":"python","title":"팩토리얼 계산","topic":"반복문","level":"입문","statement":"0 이상의 정수 N을 입력받으시오. 반복문으로 팩토리얼 N!을 계산해 출력하시오. 0!은 1이며, math.factorial은 사용하지 마시오."},{"id":"PY-043","language":"python","title":"거듭제곱 반복 계산","topic":"반복문","level":"입문","statement":"정수 A와 0 이상의 정수 B를 입력받으시오. 반복문으로 A의 B제곱을 계산하여 출력하시오. B가 0이면 A가 0이어도 결과를 1로 계산하며, ** 연산자는 사용하지 마시오."},{"id":"PY-044","language":"python","title":"특정 단 구구단","topic":"반복문","level":"입문","statement":"정수 N(2~9)을 입력받으시오. N단 구구단을 N*1=결과부터 N*9=결과까지 한 줄에 하나씩 총 9줄 출력하시오. 출력에 공백을 넣지 마시오."},{"id":"PY-045","language":"python","title":"2~9단 전체 구구단","topic":"반복문","level":"입문","statement":"입력 없이 2단부터 9단까지 구구단을 순서대로 출력하시오. 각 단의 1~9 곱셈식을 한 줄씩 출력하여 총 72줄로 만들고, 단 사이에 빈 줄은 넣지 마시오."},{"id":"PY-046","language":"python","title":"별 직사각형 출력","topic":"반복문","level":"입문","statement":"양의 정수 R과 C를 입력받으시오. 별표(*) C개를 공백 없이 한 줄에 출력하고, 이를 R줄 반복하시오."},{"id":"PY-047","language":"python","title":"왼쪽 정렬 별 삼각형","topic":"반복문","level":"입문","statement":"양의 정수 N을 입력받으시오. 첫 줄에는 별표(*) 1개, 다음 줄에는 2개씩 한 개씩 늘려 N번째 줄에는 N개를 출력하시오. 별표 사이에 공백을 넣지 마시오."},{"id":"PY-048","language":"python","title":"역삼각형 출력","topic":"반복문","level":"입문","statement":"양의 정수 N을 입력받으시오. 첫 줄에 별표(*) N개를 출력하고, 다음 줄마다 하나씩 줄여 마지막 줄에는 1개를 출력하시오."},{"id":"PY-049","language":"python","title":"정수 자릿수 계산","topic":"반복문","level":"입문","statement":"0 이상의 정수 N을 입력받으시오. 십진수 자릿수를 출력하시오. 0도 한 자리로 계산하며, 문자열로 변환하지 마시오."},{"id":"PY-050","language":"python","title":"정수 숫자 뒤집기","topic":"반복문","level":"입문","statement":"0 이상의 정수 N을 입력받으시오. 각 자리의 순서를 뒤집은 정수를 출력하시오. 앞에 오는 0은 생략하고, 문자열은 사용하지 마시오."},{"id":"PY-051","language":"python","title":"각 자리 숫자 합","topic":"반복문","level":"기초 응용","statement":"0 이상의 정수 N을 입력받으시오. 각 자리 숫자를 모두 더한 합을 출력하시오. 문자열로 변환하지 마시오."},{"id":"PY-052","language":"python","title":"소수 판별","topic":"반복문","level":"기초 응용","statement":"2 이상의 정수 N을 입력받으시오. 소수이면 PRIME, 합성수이면 COMPOSITE를 출력하시오."},{"id":"PY-053","language":"python","title":"약수 개수 계산","topic":"반복문","level":"기초 응용","statement":"양의 정수 N을 입력받으시오. N의 양의 약수 개수를 출력하시오."},{"id":"PY-054","language":"python","title":"최대공약수","topic":"반복문","level":"기초 응용","statement":"양의 정수 A와 B를 입력받으시오. 유클리드 호제법으로 두 정수의 최대공약수를 계산해 출력하시오. math.gcd는 사용하지 마시오."},{"id":"PY-055","language":"python","title":"최소공배수","topic":"반복문","level":"기초 응용","statement":"양의 정수 A와 B를 입력받으시오. 최대공약수를 계산한 뒤 두 정수의 최소공배수를 출력하시오."},{"id":"PY-056","language":"python","title":"정수 5개 리스트 합계","topic":"리스트 기초","level":"입문","statement":"정수 5개를 한 줄에 입력받아 리스트에 저장하시오. 반복문으로 합을 계산해 출력하시오. sum() 함수는 사용하지 마시오."},{"id":"PY-057","language":"python","title":"정수 5개 평균","topic":"리스트 기초","level":"기초 응용","statement":"정수 5개를 입력받으시오. 산술평균을 계산해 소수 첫째 자리까지 출력하시오."},{"id":"PY-058","language":"python","title":"리스트 최댓값·최솟값","topic":"리스트 기초","level":"기초 응용","statement":"정수 5개를 입력받으시오. 최댓값과 최솟값을 공백으로 구분해 출력하시오. max(values)는 가장 큰 값을, min(values)는 가장 작은 값을 반환하지만 이번 문제에서는 두 함수를 사용하지 마시오."},{"id":"PY-059","language":"python","title":"짝수 원소 개수","topic":"리스트 기초","level":"기초 응용","statement":"정수 5개를 입력받으시오. 짝수인 원소의 개수를 출력하시오."},{"id":"PY-060","language":"python","title":"리스트 역순 출력","topic":"리스트 기초","level":"기초 응용","statement":"정수 5개를 입력받으시오. 마지막 원소부터 첫 번째 원소까지 역순으로 공백으로 구분해 출력하시오. reversed(), reverse(), 슬라이싱은 사용하지 마시오."},{"id":"PY-061","language":"python","title":"첫 등장 위치 찾기","topic":"리스트 기초","level":"기초 응용","statement":"첫 줄에 정수 5개를, 둘째 줄에 찾을 정수 T를 입력받으시오. T가 처음 나타나는 위치를 0부터 세어 출력하고, 없으면 -1을 출력하시오."},{"id":"PY-062","language":"python","title":"리스트 값 치환","topic":"리스트 기초","level":"기초 응용","statement":"첫 줄에 정수 5개를 입력받고, 둘째 줄에 정수 A와 B를 입력받으시오. A와 같은 원소를 모두 B로 바꾸어 공백으로 구분해 출력하시오."},{"id":"PY-063","language":"python","title":"인접 원소 차이","topic":"리스트 기초","level":"기초 응용","statement":"정수 5개를 입력받으시오. 이웃한 두 원소의 차이(뒤 원소 - 앞 원소)를 순서대로 구해 총 4개를 공백으로 구분해 출력하시오."},{"id":"PY-064","language":"python","title":"버블 정렬","topic":"리스트 기초","level":"기초 응용","statement":"정수 5개를 입력받으시오. 버블 정렬로 오름차순 정렬한 뒤 공백으로 구분해 출력하시오. sort()와 sorted()는 사용하지 마시오."},{"id":"PY-065","language":"python","title":"2×3 행렬 행별 합","topic":"리스트 기초","level":"기초 응용","statement":"정수 6개를 행 순서대로 입력받아 2행 3열 리스트를 만드시오. 각 행의 합을 차례대로 공백으로 구분해 출력하시오."},{"id":"PY-066","language":"python","title":"문자 코드 확인","topic":"문자열 기초","level":"기초 응용","statement":"영문 ASCII 문자 한 개를 입력받으시오. 해당 문자의 ASCII 코드를 정수로 출력하시오."},{"id":"PY-067","language":"python","title":"소문자 대문자 변환","topic":"문자열 기초","level":"기초 응용","statement":"영문 소문자(a~z) 한 글자를 입력받으시오. 대문자로 바꾸어 출력하시오."},{"id":"PY-068","language":"python","title":"숫자 문자 검사","topic":"문자열 기초","level":"기초 응용","statement":"ASCII 문자 하나를 입력받으시오. 숫자 문자 '0'~'9'이면 DIGIT, 그렇지 않으면 OTHER를 출력하시오."},{"id":"PY-069","language":"python","title":"문자열 그대로 출력","topic":"문자열 기초","level":"기초 응용","statement":"공백 없는 영문 단어를 입력받아 그대로 출력하시오."},{"id":"PY-070","language":"python","title":"문자열 길이 직접 세기","topic":"문자열 기초","level":"기초 응용","statement":"공백 없는 영문 단어를 입력받으시오. len() 함수 없이 반복문으로 글자 수를 세어 출력하시오."},{"id":"PY-071","language":"python","title":"리스트 앞 3개 추출","topic":"리스트·튜플 응용","level":"기초 응용","statement":"정수 5개를 입력받으시오. 슬라이싱을 이용해 앞의 3개를 공백으로 구분해 출력하시오."},{"id":"PY-072","language":"python","title":"마지막 두 원소 출력","topic":"리스트·튜플 응용","level":"기초 응용","statement":"정수 5개를 입력받으시오. 음수 인덱스나 슬라이싱을 이용해 마지막 2개를 입력 순서대로 출력하시오."},{"id":"PY-073","language":"python","title":"append로 목록 늘리기","topic":"리스트·튜플 응용","level":"기초 응용","statement":"첫 줄에 정수 3개, 둘째 줄에 정수 2개를 입력받으시오. 리스트의 append(value)는 리스트 끝에 원소 value 하나를 추가하는 메서드입니다. 첫 줄의 세 정수로 리스트를 만든 뒤 둘째 줄의 두 정수를 append로 순서대로 추가하여, 최종 5개 값을 입력 순서대로 공백으로 구분해 출력하시오."},{"id":"PY-074","language":"python","title":"sorted로 새 리스트 정렬","topic":"리스트·튜플 응용","level":"기초 응용","statement":"정수 5개를 한 줄에 입력받으시오. sorted()로 오름차순 정렬한 새 리스트를 만들어 출력하시오. 원본 리스트는 변경하지 마시오."},{"id":"PY-075","language":"python","title":"리스트 얕은 복사와 별칭","topic":"리스트·튜플 응용","level":"기초 응용","statement":"첫 줄에 정수 3개를 입력받아 리스트를 만드시오. list.copy()로 복사한 후 원본 리스트의 첫 원소를 99로 바꾸시오. 복사본의 첫 원소와 변경된 원본의 첫 원소를 공백으로 구분해 출력하시오."},{"id":"PY-076","language":"python","title":"튜플 원소 읽기","topic":"리스트·튜플 응용","level":"기초 응용","statement":"정수 3개를 입력받아 튜플을 만드시오. 첫 번째 원소와 마지막 원소를 공백으로 구분해 출력하시오."},{"id":"PY-077","language":"python","title":"튜플 언패킹","topic":"리스트·튜플 응용","level":"기초 응용","statement":"정수 2개를 입력받아 튜플에 저장하시오. 튜플 언패킹으로 변수 a, b에 값을 넣고 a-b를 출력하시오."},{"id":"PY-078","language":"python","title":"리스트 컴프리헨션 제곱","topic":"리스트·튜플 응용","level":"기초 응용","statement":"정수 5개를 입력받으시오. 리스트 컴프리헨션을 사용해 각 원소의 제곱을 구하고 공백으로 구분해 출력하시오."},{"id":"PY-079","language":"python","title":"리스트 컴프리헨션 짝수","topic":"리스트·튜플 응용","level":"기초 응용","statement":"정수 5개를 입력받으시오. 짝수만 입력 순서대로 골라 공백으로 구분해 출력하시오. 짝수가 없으면 EMPTY를 출력하시오."},{"id":"PY-080","language":"python","title":"sort로 원본 리스트 정렬","topic":"리스트·튜플 응용","level":"기초 응용","statement":"정수 5개를 한 줄에 입력받아 리스트에 저장하시오. list.sort(reverse=True)를 사용해 원본 리스트를 내림차순으로 정렬하여 출력하시오. sort()의 반환값이 아닌 정렬된 리스트를 출력하시오."},{"id":"PY-081","language":"python","title":"딕셔너리 키로 점수 조회","topic":"딕셔너리·집합","level":"기초 응용","statement":"첫 줄에 서로 다른 영문 이름 3개와 점수 3개를 번갈아 입력받으시오. 둘째 줄에 조회할 이름을 입력받고, 딕셔너리에서 해당 점수를 찾아 출력하시오. 이름이 없으면 -1을 출력하시오."},{"id":"PY-082","language":"python","title":"문자 빈도 딕셔너리","topic":"딕셔너리·집합","level":"기초 응용","statement":"영문 소문자 단어를 입력받으시오. 각 문자의 등장 횟수를 세어, 문자 이름을 사전순으로 정렬해 '문자:횟수' 형식으로 한 줄씩 출력하시오."},{"id":"PY-083","language":"python","title":"딕셔너리 값 변경","topic":"딕셔너리·집합","level":"기초 응용","statement":"영문 이름 2개와 점수 2개를 번갈아 입력받아 딕셔너리에 저장하시오. 둘째 줄에 기존 이름과 새 점수를 입력받아 해당 값을 수정한 뒤 출력하시오."},{"id":"PY-084","language":"python","title":"딕셔너리 최고점 학생","topic":"딕셔너리·집합","level":"기초 응용","statement":"서로 다른 영문 이름 3개와 점수 3개를 입력받으시오. 최고 점수를 받은 학생의 이름을 출력하시오. 동점이면 먼저 입력된 학생을 선택하시오."},{"id":"PY-085","language":"python","title":"딕셔너리 키 사전순 출력","topic":"딕셔너리·집합","level":"기초 응용","statement":"서로 다른 영문 단어 3개와 숫자 3개를 번갈아 입력받으시오. 딕셔너리의 단어 키만 사전순으로 정렬해 공백으로 구분해 출력하시오."},{"id":"PY-086","language":"python","title":"집합으로 중복 제거 개수","topic":"딕셔너리·집합","level":"종합 활용","statement":"정수 5개를 입력받으시오. 중복을 제외한 서로 다른 정수의 개수를 출력하시오."},{"id":"PY-087","language":"python","title":"두 집합 교집합","topic":"딕셔너리·집합","level":"종합 활용","statement":"두 줄에 정수 4개씩 입력받으시오. 두 집합에 공통으로 있는 서로 다른 정수를 오름차순으로 출력하시오. 공통값이 없으면 EMPTY를 출력하시오."},{"id":"PY-088","language":"python","title":"두 집합 합집합","topic":"딕셔너리·집합","level":"종합 활용","statement":"두 줄에 정수 4개씩 입력받으시오. 두 집합의 합집합에서 중복을 제거한 값을 오름차순으로 출력하시오."},{"id":"PY-089","language":"python","title":"두 집합 차집합","topic":"딕셔너리·집합","level":"종합 활용","statement":"두 줄에 정수 4개씩 입력받으시오. 첫 번째 집합에만 있는 값을 오름차순으로 출력하시오. 그런 값이 없으면 EMPTY를 출력하시오."},{"id":"PY-090","language":"python","title":"문자 빈도 최댓값","topic":"딕셔너리·집합","level":"종합 활용","statement":"영문 소문자 단어를 입력받으시오. 딕셔너리로 문자별 등장 횟수를 세어 가장 자주 등장한 문자를 출력하시오. 횟수가 같으면 사전순으로 앞서는 문자를 출력하시오."},{"id":"PY-091","language":"python","title":"정수 제곱 함수","topic":"함수·종합 활용","level":"종합 활용","statement":"정수 N을 입력받으시오. 제곱값을 반환하는 square(n) 함수를 작성하고, 그 결과를 출력하시오."},{"id":"PY-092","language":"python","title":"두 정수 최댓값 함수","topic":"함수·종합 활용","level":"종합 활용","statement":"정수 2개를 입력받으시오. 두 정수 중 큰 값을 반환하는 max2(a, b) 함수를 작성하여 결과를 출력하시오. max()는 사용하지 마시오."},{"id":"PY-093","language":"python","title":"짝수 판별 함수","topic":"함수·종합 활용","level":"종합 활용","statement":"정수 하나를 입력받으시오. 짝수이면 True, 홀수이면 False를 반환하는 is_even(n) 함수를 작성하시오. 반환값에 따라 EVEN 또는 ODD를 출력하시오."},{"id":"PY-094","language":"python","title":"1부터 N 합 함수","topic":"함수·종합 활용","level":"종합 활용","statement":"양의 정수 N을 입력받으시오. 반복문으로 1부터 N까지의 합을 반환하는 sum_to(n) 함수를 작성하시오. 반환값을 출력하고 sum()은 사용하지 마시오."},{"id":"PY-095","language":"python","title":"팩토리얼 함수","topic":"함수·종합 활용","level":"종합 활용","statement":"0 이상의 정수 N을 입력받아 factorial(n) 함수를 반복문으로 구현하시오. factorial(n)은 1부터 n까지의 모든 정수를 곱한 값(n!)을 반환하며 0!은 1입니다. 내장 라이브러리 math.factorial은 사용하지 말고 직접 계산한 함수의 반환값을 출력하시오."},{"id":"PY-096","language":"python","title":"최대공약수 함수","topic":"함수·종합 활용","level":"종합 활용","statement":"양의 정수 A와 B를 입력받으시오. 최대공약수를 반환하는 gcd(a, b) 함수를 작성하시오. 결과를 출력하고 math.gcd는 사용하지 마시오."},{"id":"PY-097","language":"python","title":"리스트 합계 함수","topic":"함수·종합 활용","level":"종합 활용","statement":"정수 5개를 입력받아 리스트를 만드시오. 모든 원소의 합을 반환하는 sum_list(values) 함수를 작성하고 결과를 출력하시오. sum()은 사용하지 마시오."},{"id":"PY-098","language":"python","title":"리스트 복사 후 변경 함수","topic":"함수·종합 활용","level":"종합 활용","statement":"정수 리스트를 입력받으시오. change_first(values) 함수를 작성하여 리스트를 복사하고 복사본의 첫 원소를 99로 바꾼 뒤 복사본을 반환하시오. 원본 첫 원소와 복사본 첫 원소를 공백으로 구분해 출력하시오."},{"id":"PY-099","language":"python","title":"함수 분리 계산기","topic":"함수·종합 활용","level":"종합 활용","statement":"정수 A, B와 연산 번호(1~3)를 공백으로 구분해 입력받으시오.\n다음 세 함수를 직접 작성하시오.\n- add(a, b): 두 정수의 합(a+b)을 반환하는 덧셈 함수\n- sub(a, b): 첫 번째 수에서 두 번째 수를 뺀 차(a-b)를 반환하는 뺄셈 함수\n- mul(a, b): 두 수의 곱(a*b)을 반환하는 곱셈 함수\n연산 번호가 1이면 add(A, B), 2이면 sub(A, B), 3이면 mul(A, B)를 호출하여 반환값을 한 줄에 출력하시오."},{"id":"PY-100","language":"python","title":"점수 목록 종합 분석","topic":"함수·종합 활용","level":"종합 활용","statement":"점수 5개(각각 0~100)를 입력받으시오. analyze(scores) 함수로 평균과 최고점을 계산해 반환하고, 평균은 소수 첫째 자리까지 표시하여 최고점과 공백으로 구분해 출력하시오."}];
